INSERT INTO `destekleme_yollari` (`id`, `sira`, `baslik`, `aciklama`, `kisa_aciklama`, `tam_aciklama`, `ikon`, `resim`, `seo`, `keywords`, `description`, `durum`, `dil`, `tarih`) VALUES
(2, 2, 'İÇİMDEKİ GÜÇ', 'İÇİMDEKİ GÜÇ', 'İÇİMDEKİ GÜÇ', '<p>İ&Ccedil;İMDEKİ G&Uuml;&Ccedil;</p>', 'fas fa-award', '', 'birebir-mentorluk', 'mentorluk,birebir eğitim,öğrenci desteği', 'Birebir mentorluk ile öğrencilere profesyonel destek sağlanır.', 1, 1, '2025-11-21 12:51:17'),
(3, 2, 'Psikolojik Danışmanlık', 'Profesyonel psikologlarla öğrenci destek görüşmeleri yapılır.', 'Psikolojik destek', '<p>&Ouml;ğrencilerin stres y&ouml;netimi, motivasyon ve duygusal s&uuml;re&ccedil;lerine profesyonel psikologlar tarafından destek sunulur.</p>', 'fas fa-cloud', '', 'psikolojik-danismanlik', 'psikolojik destek,danışmanlık,öğrenci', 'Öğrenciler için uzman psikologlarla danışmanlık hizmeti.', 1, 1, '2025-11-21 12:51:17'),
(4, 3, 'Aile İletişim Eğitimi', 'Ailelerin çocuklarıyla bağlarını güçlendirecek eğitimler verilir.', 'Aile güçlendirme', '<p>Aile i&ccedil;i iletişimi artırmaya y&ouml;nelik profesyonel eğitim ve rehberlik programları uygulanır.</p>', 'fas fa-hands-helping', '', 'aile-iletisim-egitimi', 'aile eğitimi,iletişim,öğrenci-aile bağı', 'Aile iletişimini güçlendiren eğitim programı.', 1, 1, '2025-11-21 12:51:17'),
(6, 1, 'DUYGU DÜNYAM ATÖLYESİ', 'DUYGU DÜNYAM ATÖLYESİ DUYGU DÜNYAM ATÖLYESİDUYGU DÜNYAM ATÖLYESİDUYGU DÜNYAM ATÖLYESİDUYGU DÜNYAM ATÖLYESİDUYGU DÜNYAM ATÖLYESİ', '', '', '', 'Duygu_Dünyam_Atölyesİ.png', 'duygu-dunyam-atolyesi', '', '', 1, 1, '2026-01-09 19:58:02');
INSERT INTO `destekleme_yollari_settings` (`id`, `banner_baslik`, `banner_resim`, `banner_aciklama`, `sayfa_baslik_1`, `sayfa_aciklama_1`, `dil`) VALUES
(1, 'Öğrenciler İçin Destekleme Yolları', 'Sınırlar-Değerler-ve-Güven.jpg', 'Öğrencilerin akademik, sosyal ve kişisel gelişimlerini destekleyen bütüncül programlar sunuyoruz. Her öğrenciye uygun, sürdürülebilir ve etkili destek mekanizmalarıyla güçlü bir öğrenme deneyimi hedeflenmektedir.', 'Eğitimde Çok Yönlü Destek Modelleri', '<p data-start=\"1309\" data-end=\"1659\">Destekleme Yolları, &ouml;ğrencilerin eğitim yolculuklarında ihtiya&ccedil; duyabilecekleri t&uuml;m destek t&uuml;rlerini tek bir &ccedil;atı altında birleştiren kapsamlı bir yaklaşımı temsil eder. Program; birebir mentorluk, psikolojik danışmanlık, sosyal-duygusal gelişim etkinlikleri, kariyer y&ouml;nlendirme, aile iletişim desteği ve akademik g&uuml;&ccedil;lendirme &ccedil;alışmalarından oluşur.</p><br />\r\n<p>&nbsp;</p><br />\r\n<p data-start=\"1661\" data-end=\"2100\">Her &ouml;ğrencinin benzersiz gelişim yolculuğunu merkeze alan bu yapı, sınıf i&ccedil;i &ouml;ğrenmeyi g&uuml;&ccedil;lendiren uygulamalı etkinliklerle desteklenir. Eğitimli g&ouml;n&uuml;ll&uuml;ler ve uzmanlar tarafından y&uuml;r&uuml;t&uuml;len oturumlar, &ouml;ğrencilerin okulda &ouml;ğrendikleri bilgileri g&uuml;nl&uuml;k yaşamla ilişkilendirmelerini sağlar. Bu b&uuml;t&uuml;nc&uuml;l yaklaşım; &ouml;zg&uuml;veni artırır, problem &ccedil;&ouml;zme yeteneğini g&uuml;&ccedil;lendirir ve &ouml;ğrencilerin geleceğe daha sağlam adımlarla ilerlemesine yardımcı olur.</p><br />\r\n<p>&nbsp;</p><br />\r\n<p data-start=\"2102\" data-end=\"2259\">Destekleme Yolları kapsamındaki programlar, okullara &ccedil;oğunlukla &uuml;cretsiz veya d&uuml;ş&uuml;k maliyetle sunularak t&uuml;m &ouml;ğrencilerin erişimine a&ccedil;ık h&acirc;le getirilmektedir.</p>', 1);
