INSERT INTO `mail_sablonlar` (`id`, `sablon_adi`, `sablon_tip`, `konu`, `icerik`, `degiskenler`, `sertifika_ekle`, `durum`, `varsayilan`, `olusturma_tarihi`, `guncelleme_tarihi`) VALUES
(1, 'Bağış Teşekkür E-postası', 'bagis_tesekkur', 'Bağışınız için Teşekkürler - {SITE_ADI}', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <style>\r\n        body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }\r\n        .container { max-width: 600px; margin: 0 auto; padding: 20px; }\r\n        .header { background: linear-gradient(135deg, #14b8a6 0%, #0d9488 100%); color: white; padding: 30px; text-align: center; border-radius: 10px 10px 0 0; }\r\n        .content { background: #f9fafb; padding: 30px; }\r\n        .info-box { background: white; border-left: 4px solid #14b8a6; padding: 15px; margin: 20px 0; }\r\n        .footer { text-align: center; padding: 20px; color: #6b7280; font-size: 12px; }\r\n        .button { background: #14b8a6; color: white; padding: 12px 30px; text-decoration: none; border-radius: 5px; display: inline-block; margin-top: 20px; }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"container\">\r\n        <div class=\"header\">\r\n            <h1>Bağışınız için Teşekkürler!</h1>\r\n        </div>\r\n        <div class=\"content\">\r\n            <p>Sayın <strong>{AD_SOYAD}</strong>,</p>\r\n            <p><strong>{KAMPANYA}</strong> kampanyasına yapmış olduğunuz değerli bağış için teşekkür ederiz.</p>\r\n            \r\n            <div class=\"info-box\">\r\n                <h3 style=\"color: #14b8a6; margin-top: 0;\">Bağış Detayları</h3>\r\n                <p><strong>Bağış Tutarı:</strong> {TUTAR} {PARA_BIRIMI}</p>\r\n                <p><strong>Bağış Tarihi:</strong> {TARIH}</p>\r\n                <p><strong>Bağış No:</strong> {SIPARIS_NO}</p>\r\n            </div>\r\n            \r\n            <p>Bağışınız, kampanyamıza büyük bir destek olacaktır. Sizin gibi değerli bağışçılarımız sayesinde hayırlı işlere imza atmaya devam ediyoruz.</p>\r\n            \r\n            <p>Bağış sertifikanız ekli dosyalarda bulunmaktadır.</p>\r\n            \r\n            <p style=\"margin-top: 30px;\">Saygılarımızla,<br><strong>{SITE_ADI}</strong></p>\r\n        </div>\r\n        <div class=\"footer\">\r\n            <p>Bu e-posta otomatik olarak gönderilmiştir. Lütfen yanıtlamayın.</p>\r\n            <p>&copy; {YIL} {SITE_ADI} - Tüm hakları saklıdır.</p>\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>', '{ \"AD_SOYAD\":\"Bağışçı adı soyadı\",\"TUTAR\":\"Bağış tutarı\",\"PARA_BIRIMI\":\"Para birimi\",\"KAMPANYA\":\"Kampanya adı\",\"SIPARIS_NO\":\"Sipariş numarası\",\"TARIH\":\"Tarih\",\"SITE_ADI\":\"Site adı\",\"YIL\":\"Yıl\"}', 1, 1, 1, '2025-11-15 14:07:40', '2025-11-15 14:19:01');
INSERT INTO `meclis_kararlari` (`id`, `sira`, `adi`, `kararno`, `seo`, `spot`, `aciklama`, `keywords`, `description`, `durum`, `resim`, `dosya`, `tarih`, `dil`) VALUES
(1, 0, '25 Ocak 2020 Tarihli Meclis Toplantısı ve Kararlar', '010203', '25-ocak-2020-tarihli-meclis-toplantisi-ve-kararlar', 'Türkçe Lorem İpsum. Hesap makinesi sandalye layıkıyla gördüm otobüs patlıcan lambadaki cezbelendi sıla de. Türemiş sıfat eve doğru şafak uzattı çobanın. Otobüs ötekinden dolayı sıradanlıktan koştum bilgisayarı koştum gördüm bilgisayarı ama bilgisayarı.', '<p>T&uuml;rk&ccedil;e Lorem İpsum. Hesap makinesi sandalye layıkıyla g&ouml;rd&uuml;m otob&uuml;s patlıcan lambadaki cezbelendi sıla de. T&uuml;remiş sıfat eve doğru şafak uzattı &ccedil;obanın. Otob&uuml;s &ouml;tekinden dolayı sıradanlıktan koştum bilgisayarı koştum g&ouml;rd&uuml;m bilgisayarı ama bilgisayarı.</p>\r\n<p>Bahar &ccedil;akıl adresini gidecekmiş kapının kulu yazın kalemi mutlu oldular eve doğru sandalye. Patlıcan lambadaki ışık dağılımı dışarı &ccedil;ıktılar batarya kutusu domates patlıcan mutlu oldular anlamsız d&uuml;ş&uuml;n&uuml;yor mutlu oldular mıknatıslı okuma sayfası &ccedil;akıl. Yapacakmış ve duyulmamış mutlu oldular koyun balıkhaneye g&ouml;rd&uuml;m koştum koşuyorlar g&uuml;l telefonu sıradanlıktan d&uuml;ş&uuml;n&uuml;yor. De g&ouml;rd&uuml;m &ccedil;&uuml;nk&uuml; sokaklarda ona doğru salladı eve doğru biber dışarı &ccedil;ıktılar anlamsız. Ve karşıdakine sinema sokaklarda &ouml;yle ki adresini gitti masaya doğru &ccedil;obanın bahar g&uuml;l sinema bilgiyasayarı. Umut tv mutlu oldular koyun patlıcan. Nedir ne demek T&uuml;rk&ccedil;e Lorem İpsum.</p>\r\n<p>Bahar &ccedil;akıl adresini gidecekmiş kapının kulu yazın kalemi mutlu oldular eve doğru sandalye. Patlıcan lambadaki ışık dağılımı dışarı &ccedil;ıktılar batarya kutusu domates patlıcan mutlu oldular anlamsız d&uuml;ş&uuml;n&uuml;yor mutlu oldular mıknatıslı okuma sayfası &ccedil;akıl.</p>', '25 Ocak 2020 Tarihli Meclis Toplantısı ve Kararlar', '25 Ocak 2020 Tarihli Meclis Toplantısı ve Kararlar', 0, 'dernek-kapak.jpg', 'ornek_3.pdf', '22-01-2020 11:31', 1),
(2, 1, '2020 Yılı Şubat Ayı Meclis Kararları', '01020304', '2020-yili-subat-ayi-meclis-kararlari', 'Belediye Başkanı Adınız SOYADINIZ; Bu günkü meclis gündeminin tüm maddelerinin yukarıda belirtildiği şekilde görüşüldüğünü izahla; meclis üyelerine bu toplantı içinde göstermiş oldukları çaba ve çalışmalardan dolayı teşekkür ederek, alınan kararların hayırlı ve uğurlu olması temennisiyle bu günkü meclis gündeminde görüşülecek başka madde olmadığından oturuma son verilmesine meclisimizce oybirliği ile karar verildi.', '<p>5393 Sayılı Belediye Kanununun 20. maddesi uyarınca Belediye Meclisi 2020/Şubat ayı aylık olağan toplantısı yapmak &uuml;zere Belediye Meclis Salonunda 10.01.2020 Pazartesi g&uuml;n&uuml; saat 16.00&rsquo;da 2018 toplantı d&ouml;neminin 23. birleşiminin 1. oturumunun yapılması i&ccedil;in toplandı.</p>\r\n<p>&nbsp;</p>\r\n<p>- Yoklama yapılarak Belediye Meclis &Uuml;yeleri&nbsp; Adınız Soyadınız&nbsp; ve Adınız SOYADINIZ&rsquo;ın mazeretli olarak&nbsp; toplantıya katılmadığı&nbsp; tespit edildi.</p>\r\n<p>- Toplantıya katılmayan Meclis &Uuml;yelerinin mazeret dilek&ccedil;eleri meclisimizce oybirliği ile kabul edildi. Bunların dışındaki diğer t&uuml;m meclis &uuml;yelerinin toplantıya katıldığı tespit edildi.</p>\r\n<p>&nbsp;</p>\r\n<p>KARAR:1</p>\r\n<p>İmar Komisyonu Raporunun g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi. Belediyemiz İmar ve Şehircilik M&uuml;d&uuml;rl&uuml;ğ&uuml; tarafından sunulan 30/10/2018 tarih 4247 sayılı yazısı</p>\r\n<p>Oylamaya ge&ccedil;ildi. İmar Komisyonunun almış olduğu karar meclisimizce oy birliği ile kabul edildi.</p>\r\n<p>&nbsp;</p>\r\n<p>KARAR:2</p>\r\n<p>İmar Komisyonu Raporunun g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi. Belediyemiz İmar ve Şehircilik&nbsp; M&uuml;d&uuml;rl&uuml;ğ&uuml; tarafından sunulan 27/11/2018 tarih 128232/4667 sayılı yazısının g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi.</p>\r\n<p>Oylamaya ge&ccedil;ildi. İmar Komisyonunun almış olduğu karar meclisimizce oy birliği ile kabul edildi.</p>\r\n<p>&nbsp;</p>\r\n<p>KARAR:3</p>\r\n<p>İmar Komisyonu Raporunun g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi. Belediyemiz İmar ve Şehircilik&nbsp; M&uuml;d&uuml;rl&uuml;ğ&uuml; tarafından sunulan 27/11/2018 tarih 122626/4668 sayılı yazısının g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi. Oylamaya ge&ccedil;ildi. İmar Komisyonunun almış olduğu karar meclisimizce oy birliği ile kabul edildi.</p>\r\n<p>&nbsp;</p>\r\n<p>KARAR:4</p>\r\n<p>İmar Komisyonu Raporunun g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi. Belediyemiz İmar ve Şehircilik&nbsp; M&uuml;d&uuml;rl&uuml;ğ&uuml; tarafından sunulan 27/11/2018 tarih 128348/4669 sayılı yazısının g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi. Oylamaya ge&ccedil;ildi. İmar Komisyonunun almış olduğu karar meclisimizce oy birliği ile kabul edildi.</p>\r\n<p>&nbsp;</p>\r\n<p>KARAR:5</p>\r\n<p>İmar Komisyonu Raporunun g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi. Belediye Meclis &uuml;yeleri Halil İbrahim ERKAN, Muzaffer YILDIRAN, Nalan &Ccedil;OLAK, Ender DUBAZ, Sami İKİZLER, B&uuml;lent ERES tarafından sunulan 06.12.2018 tarih 2018/21691 kayıt nolu park, tesis vb. yerlere isim verilmesi konulu &ouml;nergenin g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi.</p>\r\n<p>Oylamaya ge&ccedil;ildi. İmar Komisyonunun almış olduğu karar meclisimizce oy birliği ile kabul edildi.</p>\r\n<p>&nbsp;</p>\r\n<p>KARAR:6</p>\r\n<p>Plan ve B&uuml;t&ccedil;e Komisyonu Raporunun g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi. Belediyemiz Park ve Bah&ccedil;eler M&uuml;d&uuml;rl&uuml;ğ&uuml; tarafından sunulan 05.11.2018 tarih 714 sayılı yazısı nın g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi</p>\r\n<p>Oylamaya ge&ccedil;ildi. Plan ve B&uuml;t&ccedil;e Komisyonunun almış olduğu karar meclisimizce oy birliği ile kabul edildi.</p>\r\n<p>&nbsp;</p>\r\n<p>KARAR:7</p>\r\n<p>Plan ve B&uuml;t&ccedil;e Komisyonu Raporunun g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi. Belediyemiz Zabıta M&uuml;d&uuml;rl&uuml;ğ&uuml; tarafından sunulan 15/11/2018 tarih 127296/1522 sayılı yazısının g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi.</p>\r\n<p>Oylamaya ge&ccedil;ildi. Plan ve B&uuml;t&ccedil;e Komisyonunun almış olduğu karar meclisimizce oy birliği ile kabul edildi.</p>\r\n<p>&nbsp;</p>\r\n<p>KARAR:8</p>\r\n<p>Plan ve B&uuml;t&ccedil;e Komisyonu Raporunun g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi. Belediyemiz Basın Yayın ve Halkla İlişkiler M&uuml;d&uuml;rl&uuml;ğ&uuml; tarafından sunulan 29/11/2018 tarih 128189/590 sayılı&nbsp; yazısının g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi.</p>\r\n<p>Oylamaya ge&ccedil;ildi. Plan ve B&uuml;t&ccedil;e Komisyonunun almış olduğu karar meclisimizce oy birliği ile kabul edildi.</p>\r\n<p>&nbsp;</p>\r\n<p>KARAR:9</p>\r\n<p>Plan ve B&uuml;t&ccedil;e Komisyonu Raporunun g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi. &nbsp;Belediyemiz Basın Yayın ve Halkla İlişkiler M&uuml;d&uuml;rl&uuml;ğ&uuml; tarafından sunulan 29/11/2018 tarih 128500/591 sayılı yazısının g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi.</p>\r\n<p>Oylamaya ge&ccedil;ildi. Plan ve B&uuml;t&ccedil;e Komisyonunun almış olduğu karar meclisimizce oy birliği ile kabul edildi.</p>\r\n<p>&nbsp;</p>\r\n<p>KARAR:10</p>\r\n<p>Plan ve B&uuml;t&ccedil;e Komisyonu Raporunun g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi. Belediyemiz Mali Hizmetler M&uuml;d&uuml;rl&uuml;ğ&uuml; tarafından sunulan 30/11/2018 tarih 128605/1098 sayılı yazının g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi</p>\r\n<p>Oylamaya ge&ccedil;ildi. Plan ve B&uuml;t&ccedil;e Komisyonunun almış olduğu karar meclisimizce oy birliği ile kabul edildi.</p>\r\n<p>&nbsp;</p>\r\n<p>KARAR:11</p>\r\n<p>Plan ve B&uuml;t&ccedil;e Komisyonu Raporunun g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi. Belediyemiz Emlak ve İstimlak M&uuml;d&uuml;rl&uuml;ğ&uuml; tarafından sunulan 04/12/2018 tarih 128999/1268 sayılı yazısının g&ouml;r&uuml;ş&uuml;lmesine ge&ccedil;ildi. Oylamaya ge&ccedil;ildi. Plan ve B&uuml;t&ccedil;e Komisyonunun almış olduğu karar meclisimizce oy &ccedil;okluğu ile&nbsp; kabul edildi. ( Meclis &Uuml;yeleri &nbsp;Harun CİHAN, İbrahim AKT&Uuml;RK, Mahir ARAS, Metin KANAT, Mustafa &Ccedil;ETİN, Turgut GEZER ve Ufuk BAYRAKTAR red oyu kullanmışlardır)</p>\r\n<p>&nbsp;</p>\r\n<p>BİLGİLENDİRME:</p>\r\n<p>Belediye Başkanı Adınız SOYADINIZ; Bu g&uuml;nk&uuml; meclis g&uuml;ndeminin t&uuml;m maddelerinin yukarıda belirtildiği şekilde g&ouml;r&uuml;ş&uuml;ld&uuml;ğ&uuml;n&uuml; izahla; meclis &uuml;yelerine bu toplantı i&ccedil;inde g&ouml;stermiş oldukları &ccedil;aba ve &ccedil;alışmalardan dolayı teşekk&uuml;r ederek, alınan kararların hayırlı ve uğurlu olması temennisiyle bu g&uuml;nk&uuml; meclis g&uuml;ndeminde g&ouml;r&uuml;ş&uuml;lecek başka madde olmadığından oturuma son verilmesine meclisimizce oybirliği ile karar verildi.</p>', '2020 Yılı Şubat Ayı Meclis Kararları', '2020 Yılı Şubat Ayı Meclis Kararları', 0, '', '', '25-02-2020 11:52', 1),
(3, 2, 'Dolu Kadro Derece Değişikliği', '030405', 'dolu-kadro-derece-degisikligi', 'Türkçe Lorem İpsum. Hesap makinesi sandalye layıkıyla gördüm otobüs patlıcan lambadaki cezbelendi sıla de. Türemiş sıfat eve doğru şafak uzattı çobanın. Otobüs ötekinden dolayı sıradanlıktan koştum bilgisayarı koştum gördüm bilgisayarı ama bilgisayarı.', '<p>T&uuml;rk&ccedil;e Lorem İpsum. Hesap makinesi sandalye layıkıyla g&ouml;rd&uuml;m otob&uuml;s patlıcan lambadaki cezbelendi sıla de. T&uuml;remiş sıfat eve doğru şafak uzattı &ccedil;obanın. Otob&uuml;s &ouml;tekinden dolayı sıradanlıktan koştum bilgisayarı koştum g&ouml;rd&uuml;m bilgisayarı ama bilgisayarı.</p>\r\n<p>Bahar &ccedil;akıl adresini gidecekmiş kapının kulu yazın kalemi mutlu oldular eve doğru sandalye. Patlıcan lambadaki ışık dağılımı dışarı &ccedil;ıktılar batarya kutusu domates patlıcan mutlu oldular anlamsız d&uuml;ş&uuml;n&uuml;yor mutlu oldular mıknatıslı okuma sayfası &ccedil;akıl. Yapacakmış ve duyulmamış mutlu oldular koyun balıkhaneye g&ouml;rd&uuml;m koştum koşuyorlar g&uuml;l telefonu sıradanlıktan d&uuml;ş&uuml;n&uuml;yor. De g&ouml;rd&uuml;m &ccedil;&uuml;nk&uuml; sokaklarda ona doğru salladı eve doğru biber dışarı &ccedil;ıktılar anlamsız. Ve karşıdakine sinema sokaklarda &ouml;yle ki adresini gitti masaya doğru &ccedil;obanın bahar g&uuml;l sinema bilgiyasayarı. Umut tv mutlu oldular koyun patlıcan. Nedir ne demek T&uuml;rk&ccedil;e Lorem İpsum.</p>\r\n<p>Bahar &ccedil;akıl adresini gidecekmiş kapının kulu yazın kalemi mutlu oldular eve doğru sandalye. Patlıcan lambadaki ışık dağılımı dışarı &ccedil;ıktılar batarya kutusu domates patlıcan mutlu oldular anlamsız d&uuml;ş&uuml;n&uuml;yor mutlu oldular mıknatıslı okuma sayfası &ccedil;akıl.</p>', 'Dolu Kadro Derece Değişikliği', 'Dolu Kadro Derece Değişikliği', 0, '', 'ornek_3_1.pdf', '25-01-2020 12:04', 1);
