(151, 'Magnolia Theissen', 'FreeB2BData.org Shutting Down', '246261979', 'info@freeb2bdata.org', 0, 'Hello,<br />\r\n<br />\r\nI am Magnolia Theissen from FreeB2BData<br />\r\n<br />\r\nIt is with sad regret to inform you that we are shutting down<br />\r\n<br />\r\nWe have over 252 countries and over 33 million companies available in our database with phone numbers, industries, emails, etc.<br />\r\n<br />\r\nPlease come and download your data in the next 24 hours before we shut down. <br />\r\n<br />\r\nhttps://Magnolia.freeb2bdata.org<br />\r\n<br />\r\nRegards,<br />\r\nMagnolia Theissen', '38.60.204.181', '2026-09-15 08:31:42', '1789419600'),
(152, 'Faye Studer', 'FreeB2BData.org Shutting Down', '152974679', 'info@freeb2bdata.org', 0, 'Hello,<br />\r\n<br />\r\nI am Faye Studer from FreeB2BData<br />\r\n<br />\r\nIt is with sad regret to inform you that we are shutting down<br />\r\n<br />\r\nWe have over 252 countries and over 33 million companies available in our database with phone numbers, industries, emails, etc.<br />\r\n<br />\r\nPlease come and download your data in the next 24 hours before we shut down. <br />\r\n<br />\r\nhttps://Faye.freeb2bdata.org<br />\r\n<br />\r\nRegards,<br />\r\nFaye Studer', '38.54.57.199', '2026-09-17 21:23:41', '1789592400'),
(153, 'Mark McCubbin', 'FreeB2BData.org Shutting Down', '541614897', 'info@freeb2bdata.org', 1, 'Hello,<br />\r\n<br />\r\nI am Mark McCubbin from FreeB2BData<br />\r\n<br />\r\nIt is with sad regret to inform you that we are shutting down<br />\r\n<br />\r\nWe have over 252 countries and over 33 million companies available in our database with phone numbers, industries, emails, etc.<br />\r\n<br />\r\nPlease come and download your data in the next 24 hours. <br />\r\n<br />\r\nhttps://Mark.freeb2bdata.org<br />\r\n<br />\r\nRegards,<br />\r\nMark McCubbin', '130.94.115.68', '2026-09-24 19:00:03', '1790197200');
