INSERT INTO `ogrenme_deneyimi_settings` (`id`, `banner_baslik`, `banner_resim`, `sayfa_baslik_1`, `sayfa_aciklama_1`, `sayfa_baslik_2`, `sayfa_aciklama_2`) VALUES
(1, 'Öğrenme Deneyimleri', 'açılır-menü-arkaplan.jpg', '5-25 Yaş Arası İçin Sürükleyici Öğrenme', '<p>&nbsp;</p><br />\r\n<p>&nbsp;</p><br />\r\n<p class=\"fade-in-bottom animate\">G&uuml;ney Kaliforniya Gen&ccedil; Başarı Vakfı, finansal okuryazarlık, kariyer hazırlığı ve girişimcilik ruhunun geliştirilmesinde uzun vadeli sonu&ccedil;lar sağlayan y&uuml;ksek etkili programlar sunarak okulları ve eğitimcileri destekliyor.</p><br />\r\n<p>&nbsp;</p><br />\r\n<p>&nbsp;Ekonomik Başarıyı G&uuml;&ccedil;lendirmek</p><br />\r\n<p>&nbsp;</p><br />\r\n<p class=\"fade-in-bottom animate\">G&uuml;ney Kaliforniya Gen&ccedil; Başarı Okulu olarak, Kaliforniya Standartları ve Ortak &Ccedil;ekirdek Standartları ile uyumlu &ccedil;eşitli yenilik&ccedil;i programlar aracılığıyla gen&ccedil;lerin ekonomik başarılarının sahibi olmalarını sağlamaya kendimizi adadık. M&uuml;fredatımız, karma &ouml;ğrenme formatında titizlikle hazırlanmış olup, &ccedil;eşitli okullar, okul sistemleri ve eyaletler arasında aktarılabilir ve tekrarlanabilir olmasını sağlar.</p><br />\r\n<p>&nbsp;</p><br />\r\n<p>&nbsp;Uzmanca Geliştirilmiş M&uuml;fredat</p><br />\r\n<p>&nbsp;</p><br />\r\n<p class=\"fade-in-bottom animate\">&Ouml;ğrenme &ccedil;&ouml;z&uuml;mlerimiz, eğitim ve iş d&uuml;nyasından uzmanlardan oluşan bir ekip tarafından oluşturulup geliştirilmektedir. Her program, &ouml;ğrenciler i&ccedil;in y&uuml;ksek kaliteli ve etkili &ouml;ğrenme deneyimleri garanti eden titiz alfa ve beta test aşamalarından ge&ccedil;mektedir.</p><br />\r\n<p>&nbsp;</p><br />\r\n<p>&nbsp;Eğitimcileri Desteklemek</p><br />\r\n<p>&nbsp;</p><br />\r\n<p class=\"fade-in-bottom animate\">JA &Ouml;ğrenme Deneyimleri, sınıf i&ccedil;i &ouml;ğrenmeyi geliştirmek ve eğitimcilerin İngilizce Dil Sanatları, Matematik, Sosyal Bilgiler ve diğer temel i&ccedil;erik alanlarında akademik standartları karşılamalarına yardımcı olmak &uuml;zere tasarlanmıştır. Ayrıntılı korelasyonlarımız, eğitimcilerin sınıf ihtiya&ccedil;larını karşılayacak en uygun i&ccedil;eriği belirlemelerini sağlayarak &ouml;ğrencilerin kritik &ouml;ğrenme hedeflerine ulaşmalarına yardımcı olur.</p><br />\r\n<p>&nbsp;</p><br />\r\n<p>&nbsp;Programlarımızı sınıfa g&ouml;re keşfedin</p>', 'Standart Uyumumuzu Keşfedin', '<p>&nbsp;</p><br />\r\n<p>&nbsp;</p><br />\r\n<p class=\"fade-in-bottom animate\">Programlarımızın belirli eyalet ve ulusal standartlarla nasıl uyumlu olduğunu keşfetmenizi &ouml;neririz. İhtiya&ccedil;larınıza uygun ilişkileri keşfetmek ve JA\'nın eğitim hedeflerinizi nasıl destekleyebileceğini g&ouml;rmek i&ccedil;in aşağıdan bir kategori se&ccedil;in.</p><br />\r\n<p>&nbsp;</p><br />\r\n<p>&nbsp;Kaliforniya Eyalet StandartlarıMatematik ve İngilizce Standartları:İlkokulLiseOrtaokul&nbsp;3DE Okulları</p><br />\r\n<p>&nbsp;</p><br />\r\n<p class=\"fade-in-bottom animate\">Geleneksel engelleri yıkıp, eğitimin &ccedil;er&ccedil;evesini i&ccedil;eriden dışarıya yeniden tasarlamayı hedefleyen bir lise modeli.</p>');
