INSERT INTO `programlar` (`id`, `sira`, `baslik`, `aciklama`, `banner_baslik`, `banner_aciklama`, `resim`, `banner_resim`, `banner_renk1`, `banner_ara_serit`, `banner_renk2`, `tab_aktif_renk`, `detay_aciklama`, `seo`, `description`, `keywords`, `durum`, `anasayfa_durum`, `dil`, `tarih`, `banner_baslik_renk`, `banner_aciklama_renk`, `banner_baslik_renk2`, `banner_aciklama_renk2`) VALUES
(1, 0, 'DUYGU DÜNYAM ATÖLYESİ', '<h1><span style=\"font-size: 12pt;\"><span style=\"font-size: 18pt; color: #ffffff;\">Kendi duygusunu tanıyan, duygularını g&uuml;venle ifade eden ve sağlıklı bir şekilde y&ouml;netebilen &ccedil;ocuklar&hellip;</span><br /></span><br /><br /><br /></h1>', '', '', '1-Duygu-dünyam.jpeg', 'Duygu-Dünyam-Atölyesi2_1.jpg', '#d32e2e', '#ffffff', '#d32e2e', '#d32e2e', '', 'duygu-dunyam-atolyesi', 'DUYGU DÜNYAM ATÖLYESİ', '', 1, 1, 1, '2025-10-16 00:28:18', '#ffffff', '#66ff00', '#ff0000', '#000000'),
(2, 3, 'SINIRLARIMI ÖĞRENİYORUM', '<h1><span style=\"font-size: 18pt; color: #ffffff;\">Kendini korumayı, başkalarına saygı duymayı ve g&uuml;venle hayır diyebilmeyi &ouml;ğrenen &ccedil;ocuklar&hellip;</span><br /><br /></h1>', '', '', '3-Sınırlarımı-Öğreniyorum.jpeg', 'SINIRLARIMI-ÖĞRENİYORUM_1.jpg', '#d32e2e', '#ffffff', '#d32e2e', '#d32e2e', '', 'sinirlarimi-ogreniyorum', 'SINIRLARIMI ÖĞRENİYORUM', 'SINIRLARIMI ÖĞRENİYORUM', 1, 1, 1, '2025-10-16 00:28:18', '#ffffff', '#000000', '#000000', '#000000'),
(3, 4, 'ETKİLİ İLETİŞİM', '<p><span style=\"font-size: 18pt; color: #ffffff;\">Kendini net ifade eden, karşısındakini can kulağıyla dinleyen ve ilişkilerinde denge kurabilen &ccedil;ocuklar&hellip;</span><br /><br /></p>\r\n<p><br /><br /></p>', 'ETKİLİ İLETİŞİM', '<div class=\"wp-block-group programs-banner-bottom__heading is-layout-flow wp-block-group-is-layout-flow\">\r\n<p class=\"p1\"><strong>ETKİLİ İLETİŞİM</strong></p>\r\n</div>', '4-Etkili-İletişim.jpeg', 'ETKİLİ-İLETİŞİM_2.jpg', '#d32e2e', '#ffffff', '#d32e2e', '#d32e2e', '', 'etkili-iletisim', 'ETKİLİ İLETİŞİM', '', 1, 1, 1, '2025-10-16 00:28:18', '#ffffff', '#000000', '#000000', '#000000'),
(4, 4, 'KALPTEN KALBE YOL VAR', '<h1><span style=\"font-size: 18pt; color: #ffffff;\">Sevgi, saygı, dostluk ve empati farkındalığı temelinde g&uuml;venli ve dengeli ilişkiler kurabilen &ccedil;ocuklar&hellip;</span></h1>', 'KALPTEN KALBE YOL VAR', '<div class=\"wp-block-elevation-spacer spacer spacer__small\" data-block-id=\"spacer\" aria-hidden=\"true\">\r\n<p class=\"p1\"><strong>KALPTEN KALBE YOL VAR</strong></p>\r\n</div>', '5-Kalpten-Kalbe-yol-var.jpeg', 'KALPTEN-KALBE-YOLVAR_1.jpg', '#d32e2e', '#ffffff', '#d32e2e', '#d32e2e', '', 'kalpten-kalbe-yol-var', 'KALPTEN KALBE YOL VAR', 'KALPTEN KALBE YOL VAR', 1, 1, 1, '2025-10-16 00:28:18', '#ffffff', '#000000', '#000000', '#000000'),
(5, 2, 'İÇİMDEKİ GÜÇ', '<h1><span style=\"color: #ecf0f1; font-size: 18pt;\">Zorluklarla başa &ccedil;ıkabilen, sabırla devam etme iradesi g&ouml;steren ve kendine g&uuml;venen &ccedil;ocuklar&hellip;</span></h1>', '', '', '2-içimdeki_güç.jpeg', 'İÇİMDEKİ-GÜÇ_1.jpg', '#d32e2e', '#ffffff', '#d32e2e', '#d32e2e', '', 'icimdeki-guc', 'İÇİMDEKİ GÜÇ', 'İÇİMDEKİ GÜÇ', 1, 1, 1, '2025-11-21 12:52:21', '#ffffff', '#000000', '#000000', '#000000'),
(8, 6, 'SÖZ AHLAKI', '<h1><span style=\"font-size: 18pt; color: #ffffff;\">S&ouml;z&uuml;n g&uuml;c&uuml;n&uuml; hitabet, d&uuml;r&uuml;stl&uuml;k ve adaletle birlikte kullanmayı &ouml;ğrenen &ccedil;ocuklar&hellip;</span></h1>', 'SÖZ AHLAKI', '<p class=\"p1\"><strong>S&Ouml;Z AHLAKI</strong></p>', '6-Söz-Ahlakı.jpeg', 'SÖZ-AHLAKI_2.jpg', '#d32e2e', '#ffffff', '#d32e2e', '#d32e2e', '', 'soz-ahlaki', 'SÖZ AHLAKI', 'SÖZ AHLAKI', 1, 1, 1, '2026-01-06 15:26:34', '#ffffff', '#000000', '#000000', '#000000'),
(9, 7, 'GÖREV BİLİNCİ', '<h1><span style=\"color: #ffffff; font-size: 18pt;\">Sorumluluk alabilen, birlikte hareket edebilen ve yardımlaşan &ccedil;ocuklar&hellip;</span></h1>', 'GÖREV BİLİNCİ', '<p class=\"p1\"><strong>G&Ouml;REV BİLİNCİ</strong></p>', '7-Görev-Bilinci.jpeg', 'GÖREVBİLİNCİ_2.jpg', '#d32e2e', '#ffffff', '#d32e2e', '#d32e2e', '', 'gorev-bilinci', 'GÖREV BİLİNCİ', 'GÖREV BİLİNCİ', 1, 1, 1, '2026-01-06 15:27:23', '#ffffff', '#000000', '#000000', '#000000'),
(10, 8, 'ZAMAN YÖNETİMİ', '<p><span style=\"font-size: 18pt; color: #ffffff;\">Zamanı planlayan, ekranla sağlıklı ilişki kuran ve dijital sınırlarını y&ouml;netebilen &ccedil;ocuklar&hellip;</span></p>', 'ZAMAN YÖNETİMİ', '<p class=\"p1\"><strong>ZAMAN Y&Ouml;NETİMİ</strong></p>', '8-Zaman-Yönetimi.jpeg', 'ZAMAN-YÖNETİMİ_1.jpg', '#d32e2e', '#ffffff', '#d32e2e', '#d32e2e', '', 'zaman-yonetimi', 'ZAMAN YÖNETİMİ', 'ZAMAN YÖNETİMİ', 1, 1, 1, '2026-01-06 15:27:51', '#ffffff', '#000000', '#000000', '#000000');
INSERT INTO `program_icerikleri` (`id`, `program_id`, `baslik`, `aciklama`, `resim`, `video_url`, `sira`, `durum`, `dil`, `tarih`, `gorsel_format`, `icerik_tipi`, `gorsel_desktop`, `gorsel_mobil`) VALUES
(1, 1, 'DUYGU DÜNYAM ATÖLYESİNDE NE YAPIYORUZ?', '<p>Duygu D&uuml;nyam At&ouml;lyesi bilimsel temele dayanır ve her bir &ccedil;ocuğun duygu d&uuml;nyasını g&uuml;&ccedil;lendirmeyi hedefler. S&uuml;re&ccedil; &uuml;&ccedil; aşamadan oluşur ve toplam 20 saatlik, deneyim temelli bir keşif ve farkındalık s&uuml;reci olarak tasarlanmıştır.</p>\r\n<p><strong>1.Aşama &mdash; At&ouml;lye</strong></p>\r\n<p>Merkezimizde y&uuml;r&uuml;t&uuml;len 4 haftalık s&uuml;re&ccedil;te &ccedil;ocuklar, duyguları drama &ccedil;alışmalarıyla deneyimler, P4C ve hik&acirc;ye anlatıcılığıyla d&uuml;ş&uuml;n&uuml;r ve muhakeme eder.</p>\r\n<p><strong>2.Aşama &mdash; Aile Semineri</strong></p>\r\n<p>Merkezimizde &ccedil;ocuk at&ouml;lyeleri ve aile seminerleri eş zamanlı y&uuml;r&uuml;t&uuml;l&uuml;r. Her iki programda da aynı konu ele alınır. &Ccedil;ocuklar bu i&ccedil;eriği at&ouml;lye &ccedil;alışmalarıyla deneyimlerken, aileler aynı konunun ev ortamında nasıl destekleneceğini uzmanlar eşliğinde &ouml;ğrenir.<br /><br /></p>\r\n<p><strong>3.Aşama &mdash; Ev &Ccedil;alışmaları</strong></p>\r\n<p>Aileye verilen ev uygulamalarıyla kazanımlar g&uuml;nl&uuml;k hayata taşınır. B&ouml;ylece s&uuml;re&ccedil; at&ouml;lyede bitmez, ev ortamında tekrar edilir ve kalıcı bir yaşam becerisine d&ouml;n&uuml;ş&uuml;r.</p>', '3.Bu-Sadece-Bir-Atolye-Değil_1.jpeg', '', 3, 1, '1', '2026-01-16 16:11:59', 1, 1, 'DUYGU3YY.png', ''),
(3, 1, 'BU ATÖLYEDEN SONRA ÇOCUĞUNUZDA NE DEĞİŞİR?', '<p>Duygu D&uuml;nyam At&ouml;lyemizin hedefi, &ccedil;ocuğun duygu d&uuml;nyasını g&uuml;&ccedil;lendirmektir. At&ouml;lye s&uuml;reci sonunda &ccedil;ocuk, duygularını tanıyabilen, ifade edebilen ve y&ouml;netebilen bir i&ccedil; pusula kazanır. Bu kazanımlar yalnızca at&ouml;lye ortamında kalmaz. &Ccedil;ocuğun g&uuml;nl&uuml;k yaşamına, ilişkilerine ve karakter gelişimine yerleşir.</p>', '5.çocuktaki-değişim.jpeg', '', 2, 1, '1', '2026-01-16 19:14:16', 1, 1, 'duygu2.jpg', ''),
(5, 1, 'UZMAN GÖZLEMİ VE GELİŞİM TAKİBİ', '<p>At&ouml;lye s&uuml;reci boyunca &ccedil;ocuklar, uzman psikologlar tarafından d&uuml;zenli olarak g&ouml;zlemlenir. S&uuml;recin başındaı ve sonunda yapılan gelişim değerlendirmeleriyle ailelere, &ccedil;ocuklarının duygularını fark etme, ifade etme ve duygusal tepkilerini d&uuml;zenleme bi&ccedil;imleri hakkında anlamlı geri bildirimler sunulur. <br />Ama&ccedil;; etiketlemek değil, &ccedil;ocuğun duygusal farkındalığını g&uuml;&ccedil;lendirmek ve gelişimini bilin&ccedil;li şekilde desteklemektir.</p>\r\n<p><strong><br /><br /></strong></p>', '7.uzman-gözlemi.jpeg', '', 5, 1, '1', '2026-01-16 19:15:04', 2, 1, '4uzman-gözlemi.jpg', ''),
(6, 1, 'AİLE SÜRECİ VE EVDE PEKİŞTİRME', '<p>S&uuml;re&ccedil; boyunca ebeveynlere y&ouml;nelik, merkezimizde, uzman isimler eşliğinde haftalık aile seminerleri ger&ccedil;ekleştirilir.</p>\r\n<p>Bu buluşmalarda, drama at&ouml;lyelerinde işlenen duyguların ev ortamında nasıl destekleneceği ele alınır.&nbsp; Anne-babaların &ccedil;ocukla kuracağı dil, tutum ve yaklaşım somut &ouml;rneklerle &ccedil;alışılır. Aile i&ccedil;inde g&uuml;venli iletişimi ve duygusal dengeyi g&uuml;&ccedil;lendiren pratik uygulamalar paylaşılır.</p>\r\n<p>S&uuml;reci pekiştirmek i&ccedil;in ailelere, evde birlikte uygulanabilecek etkinlik ve oyunlar sunulur. B&ouml;ylece &ccedil;ocuk &ouml;ğrendiğini g&uuml;nl&uuml;k yaşam i&ccedil;inde tekrar eder, deneyimler ve kalıcı hale getirir.</p>\r\n<p><strong><br /><br /></strong></p>', '8.aile-süreci_1.jpeg', '', 6, 1, '1', '2026-01-16 19:15:21', 2, 1, 'duygu_dünyam5.jpg', ''),
(11, 5, 'İÇİMDEKİ GÜÇ ATÖLYESİNDE NE YAPIYORUZ?', '<p>İ&ccedil;imdeki G&uuml;&ccedil; At&ouml;lyesi bilimsel temele dayanır ve her bir &ccedil;ocuğun i&ccedil;sel kapasitesini keşfetmeyi hedefler. S&uuml;re&ccedil; &uuml;&ccedil; aşamadan oluşur ve toplam 20 saatlik, deneyim temelli bir keşif ve farkındalık s&uuml;reci olarak tasarlanmıştır.<strong><br /><br /></strong> <strong>1.Aşama &mdash; At&ouml;lye</strong><br /><br />Merkezimizde y&uuml;r&uuml;t&uuml;len 4 haftalık s&uuml;re&ccedil;te &ccedil;ocuklar,&nbsp; sabır, irade ve &ouml;zg&uuml;veni drama &ccedil;alışmalarıyla deneyimler, P4C ve hik&acirc;ye anlatıcılığıyla muhakeme eder.</p>\r\n<p><strong>2.Aşama &mdash; Aile Semineri</strong></p>\r\n<p>Merkezimizde &ccedil;ocuk at&ouml;lyeleri ve aile seminerleri eş zamanlı y&uuml;r&uuml;t&uuml;l&uuml;r. Her iki programda da aynı konu ele alınır; &ccedil;ocuklar bu i&ccedil;eriği at&ouml;lye &ccedil;alışmalarıyla deneyimlerken, aileler aynı konunun ev ortamında nasıl destekleneceğini uzmanlar eşliğinde &ouml;ğrenir.<br /><strong><br />3.Aşama &mdash; Ev &Ccedil;alışmaları</strong></p>\r\n<p>Aileye verilen ev uygulamalarıyla kazanımlar g&uuml;nl&uuml;k hayata taşınır. B&ouml;ylece s&uuml;re&ccedil; at&ouml;lyede bitmez, ev ortamında tekrar edilir ve kalıcı bir yaşam becerisine d&ouml;n&uuml;ş&uuml;r.</p>', '4.Nasıl-Çalışıyoruz_1.jpeg', '', 3, 1, '1', '2026-02-05 20:25:17', 2, 1, 'içim3YY.png', ''),
(12, 5, 'BU ATÖLYEDEN SONRA ÇOCUĞUNUZDA NE DEĞİŞİR?', '<p>İ&ccedil;imdeki G&uuml;&ccedil; At&ouml;lyemizin hedefi, &ccedil;ocukların kendi i&ccedil;lerindeki g&uuml;c&uuml; keşfetmelerini, &ouml;z-disiplin ve &ouml;z-denetim becerilerini geliştirmelerini ve duygularını, davranışlarını daha bilin&ccedil;li y&ouml;netebilmelerini sağlamaktır. Bu kazanımlar yalnızca at&ouml;lye ortamında kalmaz. &Ccedil;ocuğun okul başarısına, g&uuml;nl&uuml;k yaşamına ve karakter gelişimine yerleşir.</p>', '5.çocuktaki-değişim_2.jpeg', '', 2, 1, '1', '2026-02-05 20:26:08', 2, 1, 'içimdeki-güç2.jpg', ''),
(14, 5, 'UZMAN GÖZLEMİ VE GELİŞİM TAKİBİ', '<p>At&ouml;lye s&uuml;reci boyunca &ccedil;ocuklar, uzman psikologlar tarafından d&uuml;zenli olarak g&ouml;zlemlenir. S&uuml;recin başında ve sonunda yapılan gelişim değerlendirmeleriyle ailelere, &ccedil;ocuklarının zorluklar karşısındaki tutumu, sabır becerisi ve vazge&ccedil;meden devam edebilme eğilimi hakkında anlamlı geri bildirimler sunulur.<br />Ama&ccedil;; etiketlemek değil, &ccedil;ocuğun i&ccedil;sel g&uuml;c&uuml;n&uuml; fark etmesini sağlamak ve gelişimini bilin&ccedil;li şekilde desteklemektir.</p>', '7.uzman-gözlemi_1.jpeg', '', 6, 1, '1', '2026-02-05 20:28:02', 2, 1, '4uzmang.jpg', ''),
(15, 5, 'AİLE SÜRECİ VE EVDE PEKİŞTİRME', '<p>S&uuml;re&ccedil; boyunca ebeveynlere y&ouml;nelik, merkezimizde, uzman isimler eşliğinde haftalık aile seminerleri ger&ccedil;ekleştirilir.</p>\r\n<p>Bu buluşmalarda, drama at&ouml;lyelerinde işlenen konuların ev ortamında nasıl destekleneceği ele alınır. Anne-babaların &ccedil;ocukla kuracağı dil, tutum ve yaklaşım somut &ouml;rneklerle &ccedil;alışılır. Aile i&ccedil;inde g&uuml;venli iletişimi ve duygusal dengeyi g&uuml;&ccedil;lendiren pratik uygulamalar paylaşılır.</p>\r\n<p>S&uuml;reci pekiştirmek i&ccedil;in ailelere, evde birlikte uygulanabilecek etkinlik ve oyunlar sunulur. B&ouml;ylece &ccedil;ocuk &ouml;ğrendiğini g&uuml;nl&uuml;k yaşam i&ccedil;inde tekrar eder, deneyimler ve kalıcı hale getirir.</p>', '8.aile-süreci.jpeg', '', 6, 1, '1', '2026-02-05 20:29:06', 2, 1, 'duygu_dünyam5_1.jpg', ''),
(20, 2, 'BU ATÖLYEDEN SONRA ÇOCUĞUNUZDA NE DEĞİŞİR?', '<p>Sınırlarımı &Ouml;ğreniyorum At&ouml;lyemizin hedefi, &ccedil;ocuğun fiziksel ve duygusal sınırlarını g&uuml;&ccedil;lendirmek, mahremiyet alanında kendine ait olanı koruma cesareti kazandırmaktır. Akran zorbalığı karşısında su&ccedil;luluk duymadan hayır diyebilmek, dijital d&uuml;nyada sınırlarını korumasını ve toplumsal ilişkilerde hem kendi alanını hem başkalarının alanını g&ouml;zetmesini sağlamaktır. Bu kazanımlar yalnızca at&ouml;lye ortamında kalmaz. &Ccedil;ocuğun g&uuml;nl&uuml;k yaşamına, ilişkilerine ve karakter gelişimine yerleşir.<br /><br /></p>', '5.çocuktaki-değişim_1.jpeg', '', 2, 1, '1', '2026-02-05 20:52:01', 2, 1, 'sınır2.jpg', ''),
(22, 2, 'UZMAN GÖZLEMİ VE GELİŞİM TAKİBİ', '<p>At&ouml;lye s&uuml;reci boyunca &ccedil;ocuklar, uzman psikologlar tarafından d&uuml;zenli olarak g&ouml;zlemlenir. S&uuml;recin başında ve sonunda yapılan gelişim değerlendirmeleriyle ailelere, &ccedil;ocuklarının sınır koyma becerileri, duygusal tepkileri ve sosyal ilişkilerdeki tutumları hakkında anlamlı geri bildirimler sunulur. <br />Ama&ccedil;; etiketlemek değil, &ccedil;ocuğu daha iyi tanımak ve gelişimini bilin&ccedil;li şekilde desteklemektir.</p>', '7.uzman-gözlemi_2.jpeg', '', 6, 1, '1', '2026-02-05 21:40:44', 2, 1, '4y.jpg', ''),
(23, 2, 'AİLE SÜRECİ VE EVDE PEKİŞTİRME', '<p>S&uuml;re&ccedil; boyunca ebeveynlere y&ouml;nelik, merkezimizde, uzman isimler eşliğinde haftalık aile seminerleri ger&ccedil;ekleştirilir.<br /><br />Bu buluşmalarda, drama at&ouml;lyelerinde işlenen konuların ev ortamında nasıl destekleneceği ele alınır. &Ccedil;ocuğun kazandığı sınır bilincinin ev ortamında bir ceza değil, koruyucu bir &ccedil;er&ccedil;eve olarak yaşanmasını hedefler. Anne-babaların &ccedil;ocukla kuracağı dil, tutum ve yaklaşım somut &ouml;rneklerle &ccedil;alışılır. Aile i&ccedil;inde g&uuml;venli iletişimi ve duygusal dengeyi g&uuml;&ccedil;lendiren pratik uygulamalar paylaşılır. <br /><br />S&uuml;reci pekiştirmek i&ccedil;in ailelere, evde birlikte uygulanabilecek etkinlik ve oyunlar sunulur. B&ouml;ylece &ccedil;ocuk &ouml;ğrendiğini g&uuml;nl&uuml;k yaşam i&ccedil;inde tekrar eder, deneyimler ve kalıcı hale getirir.<br /><br /><br /></p>', '8.aile-süreci_2.jpeg', '', 6, 1, '1', '2026-02-05 21:42:02', 2, 1, '5.jpg', ''),
(27, 3, 'BU ATÖLYEDEN SONRA ÇOCUĞUNUZDA NE DEĞİŞİR?', '<p>Etkili İletişim At&ouml;lyesimizin hedefi, &ccedil;ocuğun sosyal becerisini g&uuml;&ccedil;lendirmektir. At&ouml;lye s&uuml;reci sonunda &ccedil;ocuk, kendini daha net ifade edebilen, dinlemenin ilişkiyi g&uuml;&ccedil;lendirdiğini fark eden ve fikir ayrılıklarında iletişimden kopmayan bir duruş kazanır. Bu kazanımlar yalnızca at&ouml;lye ortamında kalmaz. &Ccedil;ocuğun okul hayatına, arkadaşlık bağlarına ve aile i&ccedil;i iletişimine yerleşir.</p>', '5.çocuktaki-değişim_3.jpeg', '', 2, 1, '1', '2026-02-05 21:56:45', 2, 1, 'etkili2.jpg', ''),
(30, 3, 'AİLE SÜRECİ VE EVDE PEKİŞTİRME', '<p>S&uuml;re&ccedil; boyunca ebeveynlere y&ouml;nelik, merkezimizde, uzman isimler eşliğinde haftalık aile seminerleri ger&ccedil;ekleştirilir. <br /><br />Bu buluşmalarda, evdeki iletişim dilinin etkili kullanma yolları somut &ouml;rneklerle ele alınır. Anne-babaların &ccedil;ocukla kuracağı sağlıklı diyalog y&ouml;ntemleri &uuml;zerinde &ccedil;alışılır. <br /><br />S&uuml;reci pekiştirmek i&ccedil;in ailelere, evde birlikte uygulanabilecek etkinlik ve oyunlar sunulur. B&ouml;ylece &ccedil;ocuk &ouml;ğrendiklerini g&uuml;nl&uuml;k yaşam i&ccedil;inde tekrar eder, deneyimler ve kalıcı hale getirir.</p>', '8.aile-süreci_3.jpeg', '', 8, 1, '1', '2026-02-05 22:00:25', 2, 1, '5_1.jpg', ''),
(32, 3, 'BİZİMLE TANIŞIN', '<p>Her &ccedil;ocuk kendini doğru ifade etmeyi ve anlaşıldığını hissetmeyi hak eder. Bu beceri tesad&uuml;fen değil, bilin&ccedil;li bir destek ve sağlıklı bir modelle inşa edilir. Bu s&uuml;reci yerinde tanımak ve ilk adımı atmak i&ccedil;in sizi merkezimize bekliyoruz.</p>', '10.iletisim_3.jpeg', '', 9, 1, '1', '2026-02-05 22:06:05', 2, 1, '6y_3.jpg', ''),
(35, 4, 'BU ATÖLYEDEN SONRA ÇOCUĞUNUZDA NE DEĞİŞİR?', '<p>Kalpten Kalbe Yol Var At&ouml;lyemizin hedefi &ccedil;ocuğun ilişki kurma kapasitesini geliştirmektir. At&ouml;lye s&uuml;reci sonunda &ccedil;ocuk; karşısındakinin duygusunu fark eden, saygıyı korkuyla değil bilin&ccedil;le kuran ve sevgiyi somut davranışlara d&ouml;n&uuml;şt&uuml;rebilen bir hassasiyet kazanır. Bu kazanımlar sadece arkadaşlıklarında değil, aile i&ccedil;indeki paylaşımlarında ve karakter gelişiminde de kalıcı izler bırakır.</p>', '5.çocuktaki-değişim_4.jpeg', '', 2, 1, '1', '2026-02-05 22:17:33', 2, 1, 'kalp2.jpg', ''),
(37, 4, 'UZMAN GÖZLEMİ VE GELİŞİM TAKİBİ', '<p>At&ouml;lye s&uuml;reci boyunca &ccedil;ocuklar, uzman psikologlar tarafından d&uuml;zenli olarak g&ouml;zlemlenir. S&uuml;recin başında ve sonunda yapılan gelişim değerlendirmeleriyle ailelere; &ccedil;ocuklarının ilişki kurma bi&ccedil;imi, empati d&uuml;zeyi ve duygusal tepkileri hakkında farkındalık kazandıran geri bildirimler sunulur.<br />Ama&ccedil;; etiketlemek değil, &ccedil;ocuğu daha derinlikli tanımak ve gelişimini bilin&ccedil;li şekilde desteklemektir.</p>', '7.uzman-gözlemi_4.jpeg', '', 4, 1, '1', '2026-02-05 22:20:47', 2, 1, '4_1.jpg', ''),
(38, 4, 'AİLE SÜRECİ VE EVDE PEKİŞTİRME', '<p>S&uuml;re&ccedil; boyunca ebeveynlere y&ouml;nelik, merkezimizde uzman isimler eşliğinde haftalık aile seminerleri ger&ccedil;ekleştirilir.</p>\r\n<p>Bu buluşmalarda; eşler arası saygının &ccedil;ocuğa yansımaları ve empatiyi g&uuml;nl&uuml;k hayatta modellemenin d&ouml;n&uuml;şt&uuml;r&uuml;c&uuml; g&uuml;c&uuml; somut &ouml;rneklerle ele alınır. Anne-babaların &ccedil;ocukla kuracağı duygusal bağın dili &ccedil;alışılır. <br /><br />S&uuml;reci pekiştirmek i&ccedil;in ailelere, evde birlikte uygulanabilecek etkinlikler sunulur. B&ouml;ylece &ccedil;ocuk &ouml;ğrendiklerini g&uuml;nl&uuml;k yaşam i&ccedil;inde tekrar eder, deneyimler ve kalıcı hale getirir.</p>', '8.aile-süreci_4.jpeg', '', 5, 1, '1', '2026-02-05 22:21:45', 2, 1, '5_3.jpg', ''),
(43, 8, 'BU ATÖLYEDEN SONRA ÇOCUĞUNUZDA NE DEĞİŞİR?', '<p>S&ouml;z Ahlakı At&ouml;lyemizin hedefi &ccedil;ocukların toplum &ouml;n&uuml;nde daha rahat ve tutarlı konuşmalarını desteklerken hitabet becerilerini geliştirmektir. Bu s&uuml;re&ccedil;te d&uuml;r&uuml;stl&uuml;k ve adalet kavramları ele alınarak s&ouml;z ile doğruluk arasındaki ilişki &uuml;zerinde durulur. B&ouml;ylece &ccedil;ocuklar, konuşmanın yalnızca bir ifade bi&ccedil;imi değil, sorumluluk taşıyan bir alan olduğunu fark etmeye başlar.</p>', '5.çocuktaki-değişim_5.jpeg', '', 2, 1, '1', '2026-02-05 22:34:41', 2, 1, 'söz2.jpg', ''),
(45, 8, 'UZMAN GÖZLEMİ VE GELİŞİM TAKİBİ', '<p>At&ouml;lye s&uuml;reci boyunca &ccedil;ocuklar, uzman psikologlar tarafından d&uuml;zenli olarak g&ouml;zlemlenir. S&uuml;recin başında ve sonunda yapılan gelişim değerlendirmeleriyle ailelere; &ccedil;ocuklarının s&ouml;z kullanımı, d&uuml;r&uuml;stl&uuml;k eğilimi ve adalet algısı hakkında farkındalık kazandıran geri bildirimler sunulur.<br />Ama&ccedil;; &ouml;l&ccedil;mek değil, &ccedil;ocuğu daha iyi tanımak ve gelişimini bilin&ccedil;li şekilde desteklemektir.</p>', '7.uzman-gözlemi_5.jpeg', '', 4, 1, '1', '2026-02-06 09:18:37', 2, 1, '4_2.jpg', ''),
(46, 8, 'AİLE SÜRECİ VE EVDE PEKİŞTİRME', '<p>S&uuml;re&ccedil; boyunca ebeveynlere y&ouml;nelik, merkezimizde uzman isimler eşliğinde haftalık aile seminerleri ger&ccedil;ekleştirilir. <br /><br />Bu buluşmalarda, drama at&ouml;lyelerinde geliştirilen topluluk &ouml;n&uuml;nde konuşma ve hitabet becerilerinin ev ortamında nasıl g&uuml;&ccedil;lendirileceği ele alınır. Anne-babaların kullandığı dilin, &ccedil;ocuğun &ouml;zg&uuml;venine ve ifade cesaretine etkisi somut &ouml;rneklerle &ccedil;alışılır. Doğruyu a&ccedil;ık&ccedil;a s&ouml;yleyebilme, fikir beyan ederken adaleti g&ouml;zetme ve d&uuml;r&uuml;stl&uuml;kten taviz vermeme gibi başlıklar aile i&ccedil;i senaryolar &uuml;zerinden uygulamalı olarak değerlendirilir.<br /><br />S&uuml;reci pekiştirmek i&ccedil;in ailelere, evde birlikte uygulanabilecek etkinlik ve oyunlar sunulur. B&ouml;ylece &ccedil;ocuk &ouml;ğrendiğini g&uuml;nl&uuml;k yaşam i&ccedil;inde tekrar eder, deneyimler ve kalıcı hale getirir.</p>', '8.aile-süreci_5.jpeg', '', 5, 1, '1', '2026-02-06 09:19:07', 2, 1, '5_2.jpg', ''),
(51, 9, 'BU ATÖLYEDEN SONRA ÇOCUĞUNUZDA NE DEĞİŞİR?', '<p>G&ouml;rev Bilinci At&ouml;lyemizin hedefi, &ccedil;ocuğunuzun sorumluluk almaktan ka&ccedil;ınan değil, sorumluluğu fark eden bir duruş geliştirmesini sağlamaktır. S&uuml;re&ccedil; boyunca takım &ccedil;alışması, vatanseverlik ve yardımlaşma değerleri ele alınarak g&ouml;revin yalnızca yapılacak bir iş değil, bir katkı alanı olduğu vurgulanır. B&ouml;ylece &ccedil;ocuk, kendisine verilen g&ouml;revi hatırlatılmadan yerine getirmeye, ekip i&ccedil;inde aktif rol almaya ve yardımlaşmayı doğal bir tutum olarak benimsemeye başlar. Sorumluluğun y&uuml;k değil, karakterini g&uuml;&ccedil;lendiren bir değer olduğunu fark eder.</p>', '', '', 2, 1, '1', '2026-02-06 09:53:18', 0, 1, 'görev2.jpg', ''),
(53, 9, 'UZMAN GÖZLEMİ VE GELİŞİM TAKİBİ', '<p>At&ouml;lye s&uuml;reci boyunca &ccedil;ocuklar, uzman psikologlar tarafından d&uuml;zenli olarak g&ouml;zlemlenir. S&uuml;recin başında ve sonunda yapılan gelişim değerlendirmeleriyle ailelere; &ccedil;ocuklarının sorumluluk alma bi&ccedil;imi, ekip i&ccedil;indeki rol&uuml; ve yardımlaşma eğilimi hakkında farkındalık kazandıran geri bildirimler sunulur.<br />Ama&ccedil;; etiketlemek değil, &ccedil;ocuğu daha iyi tanımak ve gelişimini bilin&ccedil;li şekilde desteklemektir.</p>', '', '', 4, 1, '1', '2026-02-06 09:56:26', 0, 1, '4_3.jpg', ''),
(54, 9, 'AİLE SÜRECİ VE EVDE PEKİŞTİRME', '<p>S&uuml;re&ccedil; boyunca ebeveynlere y&ouml;nelik, merkezimizde uzman isimler eşliğinde haftalık aile seminerleri ger&ccedil;ekleştirilir.</p>\r\n<p>Bu buluşmalarda, evde sorumluluk paylaşımı ve &ccedil;ocuğa g&ouml;rev verirken kullanılan dilin &ouml;nemi somut &ouml;rneklerle ele alınır. Yardımlaşmayı g&uuml;nl&uuml;k hayatta modellemenin aile bağlarını nasıl g&uuml;&ccedil;lendirdiği &ccedil;alışılır. Ayrıca vatanseverliğin yalnızca bir duygu değil; yaşadığı topluma, &ccedil;evresine ve ortak değerlere karşı bilin&ccedil;li bir sorumluluk olduğu &uuml;zerinde durulur.<br /><br />S&uuml;reci pekiştirmek i&ccedil;in ailelere, evde birlikte uygulanabilecek etkinlikler sunulur. B&ouml;ylece &ccedil;ocuk &ouml;ğrendiğini g&uuml;nl&uuml;k yaşam i&ccedil;inde tekrar eder, deneyimler ve kalıcı hale getirir.</p>', '', '', 5, 1, '1', '2026-02-06 09:57:09', 0, 1, '5_4.jpg', ''),
(59, 10, 'BU ATÖLYEDEN SONRA ÇOCUĞUNUZDA NE DEĞİŞİR?', '<p>Zaman Y&ouml;netimi At&ouml;lyemizin hedefi, zamanı &ccedil;ocuğunuz i&ccedil;in bir baskı ve tartışma konusu olmaktan &ccedil;ıkarıp y&ouml;netilebilir bir d&uuml;zene d&ouml;n&uuml;şt&uuml;rmektir.</p>\r\n<p>S&uuml;re&ccedil; sonunda &ccedil;ocuk; ekran karşısında kontrol edilen değil, kendi s&uuml;resini dengeleyebilen bir tutum geliştirir. Ne zaman ders &ccedil;alışacağını, ne zaman dinleneceğini ve ne zaman dijital d&uuml;nyada vakit ge&ccedil;ireceğini planlayabilen bir bilin&ccedil; kazanır.</p>\r\n<p>Bu değişim yalnızca ders başarısına değil; odaklanma s&uuml;resine, uyku d&uuml;zenine, aile i&ccedil;i &ccedil;atışmaların azalmasına ve sorumluluklarını ertelemeden yerine getirmesine yansır. Ama&ccedil; ekranı yasaklamak değil, &ccedil;ocuğun zamanı &uuml;zerinde s&ouml;z sahibi olmasını sağlamaktır.</p>', '', '', 2, 1, '1', '2026-02-06 10:14:52', 0, 1, 'zaman2.jpg', ''),
(61, 10, 'UZMAN GÖZLEMİ VE GELİŞİM TAKİBİ', '<p>At&ouml;lye s&uuml;reci boyunca &ccedil;ocuklar, uzman psikologlar tarafından d&uuml;zenli olarak g&ouml;zlemlenir. S&uuml;recin başında ve sonunda yapılan gelişim değerlendirmeleriyle ailelere; &ccedil;ocuklarının zaman kullanımı, ekranla ilişkisi ve sınır koyma becerileri hakkında farkındalık kazandıran geri bildirimler sunulur.<br />Ama&ccedil;; kontrol etmek değil, &ccedil;ocuğu bilin&ccedil;lendirmek ve gelişimini desteklemektir.</p>', '', '', 4, 1, '1', '2026-02-06 10:22:30', 0, 1, '4_4.jpg', ''),
(62, 10, 'AİLE SÜRECİ VE EVDE PEKİŞTİRME', '<p>S&uuml;re&ccedil; boyunca ebeveynlere y&ouml;nelik, merkezimizde uzman isimler eşliğinde haftalık aile seminerleri ger&ccedil;ekleştirilir. <br /><br />Bu buluşmalarda; ekran kullanımı ve planlama konusunda evde uygulanabilir d&uuml;zen kurma y&ouml;ntemleri ve dengeli rehberlik yaklaşımları ele alınır. B&ouml;ylece &ccedil;ocuk hatırlatılarak değil, kendi programını y&ouml;neterek disiplin geliştirir. Kalıcı değişim evde kurulan bilin&ccedil;li d&uuml;zenle m&uuml;mk&uuml;nd&uuml;r.&nbsp;</p>\r\n<p>S&uuml;reci pekiştirmek i&ccedil;in ailelere, evde birlikte uygulanabilecek etkinlik ve oyunlar sunulur. B&ouml;ylece &ccedil;ocuk &ouml;ğrendiğini g&uuml;nl&uuml;k yaşam i&ccedil;inde tekrar eder, deneyimler ve kalıcı hale getirir.</p>\r\n<p><br /><br /><br /><br /><br /></p>', '', '', 5, 1, '1', '2026-02-06 10:23:14', 0, 1, '5_5.jpg', ''),
(66, 1, 'DUYGULAR BİR YOLCULUKTUR', '<p>Mutluluk, &ouml;fke, korku, &uuml;z&uuml;nt&uuml;&hellip;<br />&Ccedil;ocuklar bu duygularla doğar. Ve doğru destekle, bu duygularla yaşamayı &ouml;ğrenir. Araştırmalar g&ouml;steriyor ki; &ccedil;ocukluk d&ouml;neminde duygularını tanımayı, g&uuml;venle ifade etmeyi ve sağlıklı bi&ccedil;imde y&ouml;netmeyi &ouml;ğrenen &ccedil;ocuklar; sosyal ilişkilerde daha g&uuml;&ccedil;l&uuml;, stres karşısında daha dayanıklı, kendisiyle daha barışık bireyler h&acirc;line gelir. Her &ccedil;ocuk bu beceriyi doğru y&ouml;ntemlerle geliştirebilir.</p>\r\n<p>&nbsp;</p>', '1._DUYGU.jpeg', '', 1, 1, '1', '2026-02-09 09:45:43', 1, 1, '1_3.jpg', ''),
(68, 5, 'GÜÇ, BAĞIRARAK DEĞİL İÇERİDEN GELİR', '<p>&Ouml;zg&uuml;ven, sabır, irade, dikkat y&ouml;netimi &hellip;<br />&Ccedil;ocuklar bu i&ccedil;sel potansiyelle doğar. Ve doğru destekle, bu g&uuml;c&uuml; fark edip kullanmayı &ouml;ğrenir. Araştırmalar g&ouml;steriyor ki; &ccedil;ocukluk d&ouml;neminde &ouml;z-d&uuml;zenleme, sabır ve irade becerilerini geliştiren &ccedil;ocuklar; zorluklar karşısında daha dayanıklı, dikkatlerini toplamada daha başarılı ve kendileriyle daha barışık fertler h&acirc;line gelir. Her &ccedil;ocuk bu i&ccedil;sel dayanıklılığı doğru y&ouml;ntemlerle geliştirebilir.</p>', '', '', 1, 1, '1', '2026-02-09 15:20:49', 0, 1, 'Çalışma-yüzeyi-1-kopya-6_2.jpg', ''),
(70, 2, 'SINIR, ENGEL DEĞİL GÜVENDİR', '<p>Kendi alanını tanımak, başkasına saygı duymak, hayır diyebilmek&hellip; <br />&Ccedil;ocuklar sosyal d&uuml;nyayı bu sınırlar aracılığıyla keşfeder. Sınır koymak; bir inatlaşma ya da &ccedil;atışma değil, &ccedil;ocuğun hem kendisini hem de karşısındakini koruyabilme becerisidir. Araştırmalar g&ouml;steriyor ki; &ccedil;ocukluk d&ouml;neminde sağlıklı sınır deneyimi yaşayan &ccedil;ocuklar, sosyal ilişkilerde daha dengeli, akran zorbalığına karşı daha dayanıklı ve duygularını daha sağlıklı y&ouml;neten fertler h&acirc;line gelir.</p>', '', '', 1, 1, '1', '2026-02-09 15:38:50', 0, 1, '1.jpg', ''),
(71, 2, 'SINIRLARIMI ÖĞRENİYORUM ATÖLYESİNDE NE YAPIYORUZ?', '<p>Sınırlarımı &Ouml;ğreniyorum At&ouml;lyesi bilimsel temele dayanır ve her bir &ccedil;ocuğun g&uuml;venli bir sosyal alan inşa etmesini hedefler. S&uuml;re&ccedil; &uuml;&ccedil; aşamadan oluşur ve toplam 20 saatlik, deneyim temelli bir keşif ve farkındalık s&uuml;reci olarak tasarlanmıştır.</p>\r\n<p><strong>1.Aşama &mdash; At&ouml;lye<br /><br /></strong> Merkezimizde y&uuml;r&uuml;t&uuml;len 4 haftalık s&uuml;re&ccedil;te &ccedil;ocuklar, sınırlarını fark etmeyi drama &ccedil;alışmalarıyla deneyimler, P4C ve hik&acirc;ye anlatıcılığıyla muhakeme eder.</p>\r\n<p><strong>2.Aşama &mdash; Aile Semineri</strong></p>\r\n<p>Merkezimizde &ccedil;ocuk at&ouml;lyeleri ve aile seminerleri eş zamanlı y&uuml;r&uuml;t&uuml;l&uuml;r. Her iki programda da aynı konu ele alınır. &Ccedil;ocuklar bu i&ccedil;eriği at&ouml;lye &ccedil;alışmalarıyla deneyimlerken, aileler aynı konunun ev ortamında nasıl destekleneceğini uzmanlar eşliğinde &ouml;ğrenir.<br /><br /></p>\r\n<p><strong>3.Aşama &mdash; Ev &Ccedil;alışmaları</strong></p>\r\n<p>Aileye verilen ev uygulamalarıyla kazanımlar g&uuml;nl&uuml;k hayata taşınır. B&ouml;ylece s&uuml;re&ccedil; at&ouml;lyede bitmez, ev ortamında tekrar edilir ve kalıcı bir yaşam becerisine d&ouml;n&uuml;ş&uuml;r.</p>', '', '', 3, 1, '1', '2026-02-09 15:39:26', 2, 1, 'Sınırlarımı3.png', ''),
(72, 3, 'İLETİŞİM DOĞUŞTAN GELİR, SAĞLIKLI İLETİŞİM ÖĞRENİLİR', '<p>Kendini anlatmak, anlamak, susabilmek, duyabilmek&hellip; <br />İletişim, sadece konuşabilmek değildir; ne s&ouml;ylediğini bilmek kadar ne zaman susacağını, ne hissettiğini s&ouml;yleyebilmek kadar karşısındakini anlayabilmektir. Araştırmalar g&ouml;steriyor ki; iletişim becerileri bilin&ccedil;li bi&ccedil;imde desteklenen &ccedil;ocuklar; sosyal ortamlarda kendilerini daha rahat ifade eder, dinlenmediklerinde &ouml;fkeye başvurmadan tepki verir ve arkadaşlık ilişkilerinde daha kalıcı bağlar kurarlar. Bu beceriler bir sorun ortaya &ccedil;ıktığında değil; erken d&ouml;nemde, yapılandırılmış s&uuml;re&ccedil;lerle gelişir.</p>', '', '', 1, 1, '1', '2026-02-09 15:43:45', 0, 1, 'Çalışma-yüzeyi-1-kopya-6.jpg', ''),
(73, 3, 'ETKİLİ İLETİŞİM ATÖLYESİNDE NE YAPIYORUZ?', '<p>Etkili İletişim At&ouml;lyesi bilimsel temele dayanır ve her bir &ccedil;ocuğun sağlıklı bağlar kurma potansiyelini geliştirmeyi hedefler. S&uuml;re&ccedil; &uuml;&ccedil; aşamadan oluşur ve toplam 20 saatlik, deneyim temelli bir keşif ve farkındalık s&uuml;reci olarak tasarlanmıştır.</p>\r\n<p><strong>1.Aşama &mdash; At&ouml;lye</strong> <br />Merkezimizde y&uuml;r&uuml;t&uuml;len 4 haftalık s&uuml;re&ccedil;te &ccedil;ocuklar, duygu ve d&uuml;ş&uuml;ncelerini saygılı bir dille ifade etmeyi drama &ccedil;alışmalarıyla deneyimler, P4C ve hik&acirc;ye anlatıcılığıyla muhakeme eder.</p>\r\n<p><strong>2.Aşama &mdash; Aile Semineri<br /></strong>Merkezimizde &ccedil;ocuk at&ouml;lyeleri ve aile seminerleri eş zamanlı y&uuml;r&uuml;t&uuml;l&uuml;r. Her iki programda da aynı konu ele alınır. &Ccedil;ocuklar bu i&ccedil;eriği at&ouml;lye &ccedil;alışmalarıyla deneyimlerken, aileler aynı konunun ev ortamında nasıl destekleneceğini uzmanlar eşliğinde &ouml;ğrenir.<br /><br /></p>\r\n<p><strong>3.Aşama &mdash; Ev &Ccedil;alışmaları<br /></strong>Aileye verilen ev uygulamalarıyla kazanımlar g&uuml;nl&uuml;k hayata taşınır. B&ouml;ylece s&uuml;re&ccedil; at&ouml;lyede bitmez, ev ortamında tekrar edilir ve kalıcı bir yaşam becerisine d&ouml;n&uuml;ş&uuml;r.</p>\r\n<p>&nbsp;</p>', '', '', 3, 1, '1', '2026-02-09 15:44:48', 0, 1, 'iletişim3.png', ''),
(74, 4, 'KALPTEN KALBE YOL VAR', '<p>Bağ kurmak, saygı duymak, empati&hellip;<br />İlişkiler, yalnızca birlikte vakit ge&ccedil;irmekle kurulmaz. Ger&ccedil;ek bağ, karşıdakini anlayabilmek ve sınırlarına saygı g&ouml;sterebilmekle oluşur. Araştırmalar g&ouml;steriyor ki; sevgi, saygı ve empati becerileri desteklenen &ccedil;ocuklar; arkadaşlık ilişkilerinde daha kalıcı bağlar kurabiliyor, &ccedil;atışma anlarında daha yapıcı tepkiler verebiliyor ve hem kendileriyle hem de başkalarıyla daha sağlıklı ilişkiler geliştiriyor. Bu nedenle ilişkisel beceriler bir problem ortaya &ccedil;ıktığında değil, erken d&ouml;nemde ve bilin&ccedil;li şekilde g&uuml;&ccedil;lendirilmelidir.</p>', '', '', 1, 1, '1', '2026-02-09 15:48:40', 0, 1, 'Kalpten1.jpg', ''),
(75, 4, 'KALPTEN KALBE YOL VAR ATÖLYESİNDE NE YAPIYORUZ?', '<p>Kalpten Kalbe Yol Var At&ouml;lyesi bilimsel temele dayanır ve her bir &ccedil;ocuğun kalpten kalbe giden o yolu keşfetmesini hedefler. S&uuml;re&ccedil; &uuml;&ccedil; aşamadan oluşur ve toplam 20 saatlik, deneyim temelli bir keşif ve farkındalık s&uuml;reci olarak tasarlanmıştır.</p>\r\n<p><strong>1.Aşama &mdash; At&ouml;lye</strong> <br /><br />Merkezimizde y&uuml;r&uuml;t&uuml;len 4 haftalık s&uuml;re&ccedil;te &ccedil;ocuklar; sevgi ve empatiyi drama &ccedil;alışmalarıyla deneyimler, P4C ve hik&acirc;ye anlatıcılığıyla&nbsp; muhakeme eder.<br /><strong><br />2.Aşama &mdash; Aile Semineri</strong></p>\r\n<p>Merkezimizde &ccedil;ocuk at&ouml;lyeleri ve aile seminerleri eş zamanlı y&uuml;r&uuml;t&uuml;l&uuml;r. Her iki programda da aynı konu ele alınır; &ccedil;ocuklar bu i&ccedil;eriği at&ouml;lye &ccedil;alışmalarıyla deneyimlerken, aileler aynı konunun ev ortamında nasıl destekleneceğini uzmanlar eşliğinde &ouml;ğrenir.<br /><br /><strong>3.Aşama &mdash; Ev &Ccedil;alışmaları</strong></p>\r\n<p>Aileye verilen ev uygulamalarıyla kazanımlar g&uuml;nl&uuml;k hayata taşınır. B&ouml;ylece s&uuml;re&ccedil; at&ouml;lyede bitmez, ev ortamında tekrar edilir ve kalıcı bir yaşam becerisine d&ouml;n&uuml;ş&uuml;r.</p>', '', '', 3, 1, '1', '2026-02-09 15:51:12', 0, 1, 'kalp-3.png', ''),
(76, 8, 'SÖZ İNSANIN AYNASIDIR ', '<p>Niyet, doğruluk, hitabet&hellip;<br />S&ouml;z, yalnızca seslerden oluşmaz. Niyet taşır, y&ouml;n verir ve bağ kurar. Doğru kullanıldığında iyileştirir, yanlış kullanıldığında incitir. Her &ccedil;ocuk konuşur, ancak s&ouml;z&uuml;n ne zaman s&ouml;yleneceğini ve&nbsp; nasıl s&ouml;yleneceğini bilmek farkındalık gerektirir. Araştırmalar g&ouml;steriyor ki; s&ouml;zl&uuml; ifade becerileri ahlaki değerlerle birlikte desteklenen &ccedil;ocuklar; kendilerini daha net ifade eder, yalan ve incitici dilden uzak durur ve topluluk i&ccedil;inde daha g&uuml;ven veren bir duruş sergilerler. Bu nedenle hitabet, sadece g&uuml;zel konuşmak değil, doğruyu doğru zamanda ve doğru şekilde s&ouml;yleyebilmektir.<br /><br /><br /><br /><br /></p>', '', '', 1, 1, '1', '2026-02-09 15:53:54', 0, 1, '1söz.jpeg', ''),
(77, 8, 'SÖZ AHLAKI ATÖLYESİNDE NE YAPIYORUZ?', '<p>S&ouml;z Ahlakı At&ouml;lyesi bilimsel temele dayanır ve her bir &ccedil;ocuğun \"s&ouml;z&uuml;n emanet olduğu\" bilincini geliştirmeyi hedefler. S&uuml;re&ccedil; &uuml;&ccedil; aşamadan oluşur ve toplam 20 saatlik, deneyim temelli bir keşif ve farkındalık s&uuml;reci olarak tasarlanmıştır.</p>\r\n<p><strong>1.Aşama &mdash; At&ouml;lye<br /><br /></strong> Merkezimizde y&uuml;r&uuml;t&uuml;len 4 haftalık s&uuml;re&ccedil;te &ccedil;ocuklar; d&uuml;r&uuml;stl&uuml;ğ&uuml; ve adil konuşmayı drama &ccedil;alışmalarıyla deneyimler, P4C ve hik&acirc;ye anlatıcılığıyla muhakeme eder.</p>\r\n<p><strong>2.Aşama &mdash; Aile Semineri</strong></p>\r\n<p>Merkezimizde &ccedil;ocuk at&ouml;lyeleri ve aile seminerleri eş zamanlı y&uuml;r&uuml;t&uuml;l&uuml;r. Her iki programda da aynı konu ele alınır; &ccedil;ocuklar bu i&ccedil;eriği at&ouml;lye &ccedil;alışmalarıyla deneyimlerken, aileler aynı konunun ev ortamında nasıl destekleneceğini uzmanlar eşliğinde &ouml;ğrenir.<br /><br /></p>\r\n<p><strong>3.Aşama &mdash; Ev &Ccedil;alışmaları</strong></p>\r\n<p>Aileye verilen ev uygulamalarıyla kazanımlar g&uuml;nl&uuml;k hayata taşınır. B&ouml;ylece s&uuml;re&ccedil; at&ouml;lyede bitmez, ev ortamında tekrar edilir ve kalıcı bir yaşam becerisine d&ouml;n&uuml;ş&uuml;r.</p>\r\n<p><br /><br /></p>', '', '', 3, 1, '1', '2026-02-09 15:54:53', 0, 1, 'söz3.png', ''),
(78, 9, 'SORUMLULUKLA BÜYÜYEN NESİL', '<p>Takım &ccedil;alışması, sorumlukuk, vatanseverlik, yardımlaşma&hellip;<br />Bir &ccedil;ocuğun g&uuml;&ccedil;l&uuml; bir karakter inşa etmesi bu d&ouml;rt temelde başlar. &Ccedil;ocuk sorumluluğu sadece &ldquo;yap denileni yapmak&rdquo; olarak &ouml;ğrenirse, denetlenmediğinde geri &ccedil;ekilir. Oysa ger&ccedil;ek sorumluluk; yapılması gerekeni fark etmek, kimse hatırlatmadan adım atmak ve kendini ailesine, ekibine, milletine ait hissetmektir. Bilimsel araştırmalar şunu g&ouml;steriyor; &ouml;z-disiplini ve iş birliği desteklenen &ccedil;ocuklar g&ouml;revlerini daha istikrarlı tamamlar, ekip i&ccedil;inde daha uyumlu hareket eder ve yardımlaşmayı kişisel &ccedil;ıkarın &ouml;n&uuml;ne koyar. Bu &ccedil;ocuklar pasif izleyici olmaz; bulunduğu ortama katkı sunar. G&ouml;rev bilinci bu y&uuml;zden emirle değil, anlamla gelişir. &Ccedil;ocuk aidiyet hissettiğinde sorumluluk y&uuml;k olmaktan &ccedil;ıkar; karakterinin doğal refleksi h&acirc;line gelir.</p>\r\n<p><br /><br /></p>\r\n<p>&nbsp;</p>', '', '', 1, 1, '1', '2026-02-09 19:14:48', 0, 1, 'görev1.jpg', ''),
(79, 9, 'GÖREV BİLİNCİ ATÖLYESİNDE NE YAPIYORUZ?', '<p>G&ouml;rev Bilinci At&ouml;lyesi bilimsel temele dayanır ve her bir &ccedil;ocuğun \"ben de yapabilirim ve katkı sunabilirim\" inancını pekiştirmeyi hedefler. S&uuml;re&ccedil; &uuml;&ccedil; aşamadan oluşur ve toplam 20 saatlik, deneyim temelli bir keşif ve farkındalık s&uuml;reci olarak tasarlanmıştır.</p>\r\n<p><strong>1.Aşama &mdash; At&ouml;lye</strong> <br /><br />Merkezimizde y&uuml;r&uuml;t&uuml;len 4 haftalık s&uuml;re&ccedil;te &ccedil;ocuklar, sorumluluk, takım &ccedil;alışması, vatanseverlik ve yardımseverlik drama &ccedil;alışmalarıyla deneyimler, P4C ve hik&acirc;ye anlatıcılığıyla muhakeme eder.</p>\r\n<p><strong>2.Aşama &mdash; Aile Semineri</strong></p>\r\n<p>Merkezimizde &ccedil;ocuk at&ouml;lyeleri ve aile seminerleri eş zamanlı y&uuml;r&uuml;t&uuml;l&uuml;r. Her iki programda da aynı konu ele alınır; &ccedil;ocuklar bu i&ccedil;eriği at&ouml;lye &ccedil;alışmalarıyla deneyimlerken, aileler aynı konunun ev ortamında nasıl destekleneceğini uzmanlar eşliğinde &ouml;ğrenir.<br /><br /></p>\r\n<p><strong>3.Aşama &mdash; Ev &Ccedil;alışmaları</strong></p>\r\n<p>Aileye verilen ev uygulamalarıyla kazanımlar g&uuml;nl&uuml;k hayata taşınır. B&ouml;ylece s&uuml;re&ccedil; at&ouml;lyede bitmez, ev ortamında tekrar edilir ve kalıcı bir yaşam becerisine d&ouml;n&uuml;ş&uuml;r.</p>', '', '', 3, 1, '1', '2026-02-09 19:16:50', 0, 1, 'GörevBilinci3.png', ''),
(80, 10, 'ZAMANIN MİMARI OLMAK', '<p>Ekran s&uuml;resi, dikkat dağınıklığı, ertelenen &ouml;devler&hellip;<br />Bug&uuml;n bir&ccedil;ok ebeveynin ortak sorunu aynı. &Ccedil;ocuk zamanı y&ouml;netemiyor,&nbsp; zaman &ccedil;ocuğu y&ouml;netiyor. Zaman durdurulamaz ama y&ouml;nlendirilebilir. &Ccedil;ocuklar ekranı bırakmayı &ccedil;oğu zaman &ldquo;yasak&rdquo; olarak algılar; plan yapmayı ise kendiliğinden &ouml;ğrenmez. Oysa planlama becerisi ve dijital sınır koyabilme alışkanlığı sistemli bi&ccedil;imde desteklendiğinde tablo değişir. Araştırmalar g&ouml;steriyor ki; zaman y&ouml;netimi ve ekran kullanımına dair &ouml;z-denetim becerileri g&uuml;&ccedil;lenen &ccedil;ocukların daha uzun s&uuml;re odaklanabildiğini, ekran karşısında daha bilin&ccedil;li tercihler yaptığını ve sorumluluklarını ertelemeden tamamladığını g&ouml;stermektedir. Bu nedenle &ccedil;&ouml;z&uuml;m, cihazı tamamen kaldırmak değil, &ccedil;ocuğa zamanı planlamayı ve ekranla sağlıklı bir mesafe kurmayı &ouml;ğretmektir. Zaman y&ouml;netimi yasaklarla değil, farkındalık, &ouml;ncelik belirleme ve uygulanabilir planlama alışkanlıklarıyla gelişir.<br />Ama&ccedil;, ekranı azaltmak değil; &ccedil;ocuğun kendi zamanının sorumluluğunu almasını sağlamaktır.</p>', '', '', 1, 1, '1', '2026-02-09 19:20:43', 0, 1, 'zaman1.png', ''),
(81, 10, 'ZAMAN YÖNETİMİ ATÖLYESİNDE NE YAPIYORUZ?', '<p>Zaman Y&ouml;netimi At&ouml;lyesi bilimsel temele dayanır ve her bir &ccedil;ocuğun anı y&ouml;netme kapasitesini geliştirmeyi hedefler. S&uuml;re&ccedil; &uuml;&ccedil; aşamadan oluşur ve toplam 20 saatlik, deneyim temelli bir keşif ve farkındalık s&uuml;reci olarak tasarlanmıştır.</p>\r\n<p><strong>1.Aşama &mdash; At&ouml;lye</strong> <br /><br />Merkezimizde y&uuml;r&uuml;t&uuml;len 4 haftalık s&uuml;re&ccedil;te &ccedil;ocuklar; zamanı planlamayı, &ouml;ncelik belirlemeyi ve sorumluluklarını ertelememeyi drama &ccedil;alışmalarıyla deneyimler, P4C ve hik&acirc;ye anlatıcılığıyla muhakeme eder.</p>\r\n<p><strong>2.Aşama &mdash; Aile Semineri</strong></p>\r\n<p>Merkezimizde &ccedil;ocuk at&ouml;lyeleri ve aile seminerleri eş zamanlı y&uuml;r&uuml;t&uuml;l&uuml;r. Her iki programda da aynı konu ele alınır; &ccedil;ocuklar bu i&ccedil;eriği at&ouml;lye &ccedil;alışmalarıyla deneyimlerken, aileler aynı konunun ev ortamında nasıl destekleneceğini uzmanlar eşliğinde &ouml;ğrenir.<br /><br /></p>\r\n<p><strong>3.Aşama &mdash; Ev &Ccedil;alışmaları</strong></p>\r\n<p>Aileye verilen ev uygulamalarıyla kazanımlar g&uuml;nl&uuml;k hayata taşınır. B&ouml;ylece s&uuml;re&ccedil; at&ouml;lyede bitmez, ev ortamında tekrar edilir ve kalıcı bir yaşam becerisine d&ouml;n&uuml;ş&uuml;r.</p>', '', '', 3, 1, '1', '2026-02-09 19:22:52', 0, 1, 'zaman3.png', ''),
(82, 1, 'BİZİMLE TANIŞIN', '<p>Her &ccedil;ocuk g&uuml;&ccedil;l&uuml; bir i&ccedil; pusula geliştirmeyi hak eder. Bu pusula tesad&uuml;fen oluşmaz, bilin&ccedil;li bir destekle inşa edilir. Bu s&uuml;reci yerinde tanımak ve ilk adımı atmak i&ccedil;in sizi merkezimize bekliyoruz.</p>', '', '', 6, 1, '1', '2026-02-16 11:59:02', 0, 1, '6y.jpg', ''),
(83, 5, 'BİZİMLE TANIŞIN', '<p>Her &ccedil;ocuk zorluklar karşısında dimdik durabilecek bir i&ccedil; g&uuml;ce sahiptir. Bu g&uuml;&ccedil; tesad&uuml;fen değil, bilin&ccedil;li bir destekle inşa edilir. Bu s&uuml;reci yerinde tanımak ve ilk adımı atmak i&ccedil;in sizi merkezimize bekliyoruz.</p>', '', '', 6, 1, '1', '2026-02-17 16:15:31', 0, 1, '6y_1.jpg', ''),
(84, 2, 'BİZİMLE TANIŞIN', '<p>Her &ccedil;ocuk sınırlarına saygı duyulmasını ve g&uuml;ven i&ccedil;inde b&uuml;y&uuml;meyi hak eder. Bu bilin&ccedil; tesad&uuml;fen değil, anlayış ve doğru bir rehberlikle inşa edilir. Bu s&uuml;reci yerinde tanımak ve ilk adımı atmak i&ccedil;in sizi merkezimize bekliyoruz.</p>', '', '', 6, 1, '1', '2026-02-17 16:15:51', 0, 1, '6y_2.jpg', ''),
(85, 8, 'BİZİMLE TANIŞIN', '<p>Her &ccedil;ocuk, s&ouml;z&uuml;n&uuml; bir g&uuml;ce ve erdeme d&ouml;n&uuml;şt&uuml;rme potansiyeline sahiptir. Bu potansiyel tesad&uuml;fen değil, bilin&ccedil;li bir eğitim ve ahlaki bir zeminle inşa edilir. Bu s&uuml;reci yerinde tanımak ve ilk adımı atmak i&ccedil;in sizi merkezimize bekliyoruz.</p>', '', '', 6, 1, '1', '2026-02-17 16:18:01', 0, 1, '6y_5.jpg', ''),
(86, 9, 'BİZİMLE TANIŞIN', '<p>Kendi g&uuml;c&uuml;n&uuml; bir faydaya d&ouml;n&uuml;şt&uuml;rmeyi &ouml;ğrenmek, her &ccedil;ocuğun gelişim yolculuğunda hak ettiği bir kazanımdır. Bu bilin&ccedil; tesad&uuml;fen değil, doğru bir rehberlik ve sağlıklı bir aidiyet zeminiyle inşa edilir. Bu s&uuml;reci yerinde tanımak ve ilk adımı atmak i&ccedil;in sizi merkezimize bekliyoruz.</p>', '', '', 6, 1, '1', '2026-02-17 16:21:51', 0, 1, '6y_6.jpg', ''),
(87, 10, 'BİZİMLE TANIŞIN', '<p>Zamanı verimli kullanmayı ve dijital d&uuml;nyada dengede kalmayı &ouml;ğrenmek, her &ccedil;ocuğun bu &ccedil;ağda hak ettiği bir donanımdır. Bu bilin&ccedil; yasaklarla değil, doğru bir rehberlik ve planlama alışkanlığıyla inşa edilir. Bu s&uuml;reci yerinde tanımak ve ilk adımı atmak i&ccedil;in sizi merkezimize bekliyoruz.</p>', '', '', 6, 1, '1', '2026-02-17 16:24:08', 0, 1, '6y_7.jpg', ''),
(88, 4, 'BİZİMLE TANIŞIN', '<p>Her &ccedil;ocuk sevgiyi nezaketle ifade etmeyi ve derin bağlar kurmayı hak eder. Bu yollar tesad&uuml;fen değil, bilin&ccedil;li bir emek ve doğru bir rehberlikle inşa edilir. Bu s&uuml;reci yerinde tanımak ve ilk adımı atmak i&ccedil;in sizi merkezimize bekliyoruz.</p>', '', '', 6, 1, '1', '2026-02-17 16:30:09', 0, 1, '6y_4.jpg', ''),
(89, 3, 'UZMAN GÖZLEMİ VE GELİŞİM TAKİBİ', '<p>At&ouml;lye s&uuml;reci boyunca &ccedil;ocuklar, uzman psikologlar tarafından d&uuml;zenli olarak g&ouml;zlemlenir. S&uuml;recin başında ve sonunda yapılan gelişim değerlendirmeleriyle ailelere, &ccedil;ocuklarının iletişim tarzı, sosyal girişkenliği ve ilişki kurma bi&ccedil;imleri hakkında farkındalık kazandıran geri bildirimler sunulur. <br />Ama&ccedil;; etiketlemek değil, &ccedil;ocuğu daha iyi tanımak ve sosyal gelişimini bilin&ccedil;li şekilde desteklemektir.</p>', '', '', 6, 1, '1', '2026-02-18 15:43:58', 0, 1, '4.jpg', '');
