INSERT INTO `testler` (`id`, `adi`, `seo`, `aciklama`, `giris_metni`, `sonuc_metni`, `durum`, `dil`, `tarih`) VALUES
(1, 'Mizaç Testi', 'mizac-testi', 'Hızlı Mizaç Testi ile mizaç tipinizi keşfedin.', 'Doğuştan gelen mizaç özelliklerini bilmek,  gelişim sürecinizi hatasız ve verimli bir şekilde yönetmenizi sağlar. Dolduracağınız bu test, potansiyelinizi en doğru şekilde değerlendirmemiz için ilk adımdır. Sizi en iyi ifade eden seçeneği işaretleyiniz.', 'Karakter yapınıza ve mizacınıza en uygun atölye çalışmalarını netleştirmek, size özel hazırlayacağımız analiz raporunu paylaşmak için sizi merkezimize davet ediyoruz.', 1, 1, '2026-03-06 00:50:11');
