INSERT INTO `test_kutulari` (`id`, `test_id`, `adim`, `harf`, `maddeler`, `enneagram_tipi`, `sira`, `durum`) VALUES
(1, 1, 1, '', 'Ciddi ve akılcı davranan\r\nİlişkilerinde mantıklı ve kuralcı\r\nMantıklı ve kontrollü davranan\r\nAyrıntıcı ve eleştirel\r\nHatalara müdahale eden\r\nPrensipli ve ilkelerine çok bağlı', 1, 1, 1),
(2, 1, 1, '', 'Çok meraklı, yenilikçi\r\nKeşfetmeyi seven\r\nNeşeli ve iyimser\r\nPratik davranan\r\nOlumsuzluğa pek takılmayan\r\nHeyecan ve coşku arayan', 7, 2, 1),
(3, 1, 1, '', 'Uyum ve denge odaklı\r\nÇatışmadan kaçınan\r\nHuzur ve sükûnet arayan\r\nAcele etmeyen\r\nAlçak gönüllü ve esnek\r\nYumuşak huylu, sabırlı', 9, 3, 1),
(4, 1, 2, '', 'Bilgiye derinlemesine meraklı\r\nAkılcı, soğukkanlı\r\nİlişkilerinde mesafeli\r\nKendine yetmeye çalışan\r\nDuygusallıktan kaçınan\r\nMüdahale etmeden uyaran', 5, 1, 1),
(5, 1, 2, '', 'Cesur, kararlı ve baskın\r\nKendinden emin\r\nMeydan okuyan\r\nSahiplenici ve otoriter\r\nRiskten kaçınmayan\r\nÇatışmadan kaçınmayan', 8, 2, 1),
(6, 1, 2, '', 'İlişkilerinde sıcak ve samimi\r\nYardım etme gereği duyan\r\nDuygusal paylaşımı seven\r\nArkadaş canlısı, sıcakkanlı\r\nÇabuk duygulanan-alınan\r\nArkadaşlık ve iletişimi seven', 2, 3, 1),
(7, 1, 3, '', 'Güven ve emniyet odaklı\r\nZihinsel netlik arayan\r\nRiski sevmeyen, kontrolcü\r\nTemkinli ve tedbirli\r\nSorgulayıcı\r\nKontrollü davranan\r\nBelirsizlikten rahatsız olan', 6, 1, 1),
(8, 1, 3, '', 'Başarı odaklı, hedef koyan\r\nKendini motive eden\r\nHırslı ve rekabetçi\r\nÖnde çıkmayı seven\r\nİmajını önemseyen\r\nDiplomatik olabilen', 3, 2, 1),
(9, 1, 3, '', 'Anlam ve derinlik arayan\r\nSezgilerini önemseyen\r\nAnlaşılmak isteyen, özgün\r\nDuyguları yoğun yaşayan\r\nİç dünyasını gözlemleyen\r\nHassas ve dost canlısı', 4, 3, 1);
INSERT INTO `test_mizac_tipleri` (`id`, `test_id`, `mizac_tipi`, `baslik`, `etiket`, `aciklama`, `renk`) VALUES
(6, 1, 1, 'Mizaç 1 -  Kusursuzluğu Arayan Mizaç', 'İdealist, İlkeli ve Disiplinli', 'Mizacınız ilkeli, düzenli ve mükemmeliyetçi bir yapıya sahiptir.', '#4a90d2'),
(7, 1, 2, 'Mizaç 2 -  Sevgiyi Arayan Mizaç', 'Yardımsever, Şefkatli ve İlişki Odaklı', 'Mizacınız sıcak, ilgili ve fedakâr bir yapıya sahiptir.', '#e74c3c'),
(8, 1, 3, 'Mizaç 3 -  Başarıyı Arayan Mizaç', 'Hırslı, Sonuç Odaklı ve Hayranlık Uyandıran', 'Mizacınız hedef odaklı, hırslı ve uyumlu bir yapıya sahiptir.', '#f39c12'),
(9, 1, 4, 'Mizaç  4 - Özgünlüğü Arayan Mizaç', 'Duyarlı, Sanatsal ve Anlam Odaklı', 'Mizacınız özgün, duygusal ve yaratıcı bir yapıya sahiptir.', '#9b59b6'),
(10, 1, 5, 'Mizaç  5 - Bilgiyi Arayan Mizaç', 'Gözlemci, Analitik ve Bağımsız', 'Mizacınız meraklı, analitik ve bağımsız bir yapıya sahiptir.', '#2ecc71'),
(11, 1, 6, 'Mizaç  6 -Güveni Arayan Mizaç', 'Sadık, Tedbirli ve Sorumluluk Sahibi', 'Mizacınız güvenilir, sorumlu ve tedbirli bir yapıya sahiptir.', '#3498db'),
(12, 1, 7, 'Mizaç 7 Keyfi Arayan Mizaç', 'Maceracı, İyimser ve Hareketli', 'Mizacınız enerjik, iyimser ve çok yönlü bir yapıya sahiptir.', '#f1c40f'),
(13, 1, 8, 'Mizaç 8 - Gücü Arayan Mizaç', 'Lider, Kararlı ve Koruyucu', 'Mizacınız güçlü, kararlı ve koruyucu bir yapıya sahiptir.', '#e67e22'),
(14, 1, 9, 'Mizaç 9 - Huzuru Arayan Mizaç', 'Barışçıl, Uyumlu ve Sakin', 'Mizacınız uyumlu, sabırlı ve kabullenici bir yapıya sahiptir.', '#1abc9c');
