INSERT INTO `yetim_bildirim_sablonlari` (`id`, `tip`, `kanal`, `dil`, `baslik`, `icerik`, `durum`) VALUES
(1, 'egitim', 'sms', 1, NULL, 'Sayın {HAMI_AD}, hamiligini yaptiginiz {YETIM_AD} isimli yetimimizin egitim durumu guncellendi: {DETAY}. Tesekkurler.', 1),
(2, 'egitim', 'email', 1, 'Eğitim Durumu Güncellemesi', 'Sayın {HAMI_AD},<br><br>Hamiliğini yaptığınız <strong>{YETIM_AD}</strong> isimli yetimimizin eğitim durumu hakkında yeni bir gelişme var:<br><br>{DETAY}<br><br>Destekleriniz için teşekkür ederiz.', 1),
(3, 'saglik', 'sms', 1, NULL, 'Sayın {HAMI_AD}, {YETIM_AD} isimli yetimimizin saglik durumu guncellendi: {DETAY}.', 1),
(4, 'saglik', 'email', 1, 'Sağlık Durumu Güncellemesi', 'Sayın {HAMI_AD},<br><br>Hamiliğini yaptığınız <strong>{YETIM_AD}</strong> isimli yetimimizin sağlık durumu hakkında bilgilendirme:<br><br>{DETAY}<br><br>Geçmiş olsun dileklerimizle.', 1),
(5, 'yardim', 'sms', 1, NULL, 'Sayın {HAMI_AD}, {YETIM_AD} adina yeni bir yardim ulastirildi: {DETAY}. Desteginiz icin tesekkurler.', 1),
(6, 'yardim', 'email', 1, 'Yardım Bilgilendirmesi', 'Sayın {HAMI_AD},<br><br>Sizin vesilenizle <strong>{YETIM_AD}</strong> isimli yetimimize yeni bir yardım ulaştırıldı:<br><br>{DETAY}<br><br>Allah kabul etsin.', 1),
(7, 'egitim', 'sms', 1, 'Eğitim Durumu Güncellemesi', 'Sayın {HAMI_AD}, Hamisi olduğunuz {YETIM_AD} isimli yetimimizin eğitim durumu güncellenmiştir: {DETAY}. Destekleriniz için teşekkür ederiz.', 1),
(8, 'saglik', 'sms', 1, 'Sağlık Raporu Eklendi', 'Sayın {HAMI_AD}, Hamisi olduğunuz {YETIM_AD} isimli yetimimizin yeni sağlık raporu sisteme eklenmiştir. Detayları panelden inceleyebilirsiniz.', 1),
(9, 'yardim', 'sms', 1, 'Yeni Yardım Yapıldı', 'Sayın {HAMI_AD}, {YETIM_AD} isimli yetimimize {DETAY} yardımı ulaştırılmıştır. Katkılarınızla yüzler gülüyor.', 1),
(10, 'egitim', 'email', 1, 'Eğitim Durumu Güncellemesi', 'Sayın {HAMI_AD},<br><br>Hamisi olduğunuz <strong>{YETIM_AD}</strong> isimli yetimimizin eğitim durumu güncellenmiştir.<br><br><strong>Detay:</strong> {DETAY}<br><br>Destekleriniz için teşekkür ederiz.<br>{KURUM_ADI}', 1);
